-- Aprenda se Divertindo · 76 · Baralho de cartões · trilha Policial · mais 500 cartões (total de 1.000)
-- Rode depois do 74-cartoes-policial.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Assuntos novos, sem repetir os 500 primeiros: lei penal no espaço, concurso de crimes, prescrição, crimes digitais,
-- competência da Justiça Federal, nulidades, júri, direitos do art. 5º, nacionalidade, abuso de autoridade, LEP, ECA,
-- Lei 8.112, processo administrativo, regência e concordância, balística e tanatologia, entre outros.
-- Cartões numerados de 2.000.000.501 a 2.000.001.000. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000000501, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Lei excepcional ou temporária continua valendo para os fatos praticados durante sua vigência, mesmo depois de revogada?", "verso": "Sim. Tem ultra-atividade: aplica-se ao fato praticado durante sua vigência.", "explicacao": "CP, art. 3º."}, {"id": 2000000502, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Qual princípio é a regra para aplicar a lei penal no espaço?", "verso": "Territorialidade: aplica-se a lei brasileira ao crime cometido no território nacional, sem prejuízo de tratados.", "explicacao": "CP, art. 5º (territorialidade temperada)."}, {"id": 2000000503, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Embarcação ou aeronave brasileira pública ou a serviço do governo: onde quer que esteja, é território brasileiro?", "verso": "Sim, para efeitos penais.", "explicacao": "CP, art. 5º, § 1º. As privadas, só em alto-mar ou espaço aéreo correspondente."}, {"id": 2000000504, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Cite casos de extraterritorialidade incondicionada.", "verso": "Crimes contra a vida ou liberdade do Presidente; contra o patrimônio ou a fé pública da União, Estados, DF, Municípios e entes da administração indireta; contra a administração pública por quem está a seu serviço; genocídio, quando o agente for brasileiro ou domiciliado no Brasil.", "explicacao": "CP, art. 7º, I."}, {"id": 2000000505, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Como se conta o prazo penal (de pena, prescrição, decadência)?", "verso": "Inclui-se o dia do começo e contam-se os dias, meses e anos pelo calendário comum.", "explicacao": "CP, art. 10. No prazo processual, o dia do começo é excluído (CPP, art. 798)."}, {"id": 2000000506, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pergunta", "frente": "Causa superveniente relativamente independente que, por si só, produz o resultado: o agente responde pelo resultado?", "verso": "Não. Responde só pelos atos anteriores.", "explicacao": "CP, art. 13, § 1º. Ex.: vítima ferida morre no incêndio do hospital."}, {"id": 2000000507, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pergunta", "frente": "Quem tem o dever de agir para evitar o resultado (garantidor)?", "verso": "Quem tem por lei obrigação de cuidado, proteção ou vigilância; quem assumiu a responsabilidade de impedir o resultado; quem criou o risco com seu comportamento anterior.", "explicacao": "CP, art. 13, § 2º (crimes omissivos impróprios)."}, {"id": 2000000508, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "lacuna", "frente": "Diz-se o crime consumado quando nele se reúnem ____ os elementos de sua definição legal.", "verso": "todos", "explicacao": "CP, art. 14, I."}, {"id": 2000000509, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pergunta", "frente": "Nos crimes agravados pelo resultado, como o agente responde pelo resultado mais grave?", "verso": "Só se o tiver causado ao menos culposamente.", "explicacao": "CP, art. 19. Ex.: lesão corporal seguida de morte (preterdolo)."}, {"id": 2000000510, "trilha": "policial", "materia": "pen", "assunto": "Erro", "tipo": "pergunta", "frente": "O que são descriminantes putativas?", "verso": "Quando o agente, por erro plenamente justificado pelas circunstâncias, supõe situação de fato que tornaria a ação legítima (ex.: legítima defesa imaginária). Isenta de pena.", "explicacao": "CP, art. 20, § 1º. Se o erro deriva de culpa, responde por culpa, se houver forma culposa."}, {"id": 2000000511, "trilha": "policial", "materia": "pen", "assunto": "Erro", "tipo": "pergunta", "frente": "Erro sobre a pessoa: por quem o agente responde?", "verso": "Considera-se a vítima pretendida, não a atingida (suas condições e qualidades).", "explicacao": "CP, art. 20, § 3º. Ex.: queria matar o pai e matou um estranho: incide a agravante de crime contra ascendente."}, {"id": 2000000512, "trilha": "policial", "materia": "pen", "assunto": "Erro", "tipo": "pares", "frente": "Aberratio ictus x aberratio criminis.", "verso": "Aberratio ictus (erro na execução): atinge pessoa diversa da pretendida; responde como se tivesse atingido a pretendida. Aberratio criminis (resultado diverso): atinge bem jurídico diverso; responde por culpa, se houver forma culposa.", "explicacao": "CP, arts. 73 e 74."}, {"id": 2000000513, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pares", "frente": "Inimputável x semi-imputável por doença mental.", "verso": "Inimputável: inteiramente incapaz de entender o caráter ilícito ou de se determinar; é isento de pena (medida de segurança). Semi-imputável: capacidade reduzida; pena reduzida de 1/3 a 2/3.", "explicacao": "CP, art. 26 e parágrafo único."}, {"id": 2000000514, "trilha": "policial", "materia": "pen", "assunto": "Concurso de pessoas", "tipo": "pergunta", "frente": "O ajuste, a determinação, a instigação e o auxílio são puníveis se o crime não chega a ser tentado?", "verso": "Não, salvo disposição expressa em contrário.", "explicacao": "CP, art. 31."}, {"id": 2000000515, "trilha": "policial", "materia": "pen", "assunto": "Concurso de pessoas", "tipo": "pergunta", "frente": "As circunstâncias de caráter pessoal se comunicam aos coautores?", "verso": "Não, salvo quando elementares do crime.", "explicacao": "CP, art. 30. Ex.: a condição de funcionário público se comunica ao particular no peculato."}, {"id": 2000000516, "trilha": "policial", "materia": "pen", "assunto": "Concurso de crimes", "tipo": "pares", "frente": "Concurso material x concurso formal.", "verso": "Material: mais de uma ação, dois ou mais crimes; somam-se as penas. Formal: uma só ação, dois ou mais crimes; aplica-se a mais grave aumentada de 1/6 até metade (salvo desígnios autônomos, quando se somam).", "explicacao": "CP, arts. 69 e 70."}, {"id": 2000000517, "trilha": "policial", "materia": "pen", "assunto": "Concurso de crimes", "tipo": "pergunta", "frente": "O que é crime continuado e qual o aumento?", "verso": "Vários crimes da mesma espécie, com semelhantes condições de tempo, lugar e modo de execução, tratados como continuação do primeiro. Aplica-se uma só pena aumentada de 1/6 a 2/3.", "explicacao": "CP, art. 71. Em crimes dolosos com violência contra vítimas diferentes, pode chegar ao triplo."}, {"id": 2000000518, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Qual o critério de cálculo da pena (sistema trifásico)?", "verso": "1ª fase: pena-base pelas circunstâncias judiciais (art. 59). 2ª: atenuantes e agravantes. 3ª: causas de diminuição e de aumento.", "explicacao": "CP, art. 68."}, {"id": 2000000519, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "A atenuante pode levar a pena abaixo do mínimo legal?", "verso": "Não.", "explicacao": "Súmula 231 do STJ."}, {"id": 2000000520, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quais os requisitos básicos do sursis (suspensão condicional da pena)?", "verso": "Pena não superior a 2 anos, réu não reincidente em crime doloso, circunstâncias favoráveis e não ser cabível a substituição por restritiva de direitos. Período de prova de 2 a 4 anos.", "explicacao": "CP, art. 77."}, {"id": 2000000521, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pares", "frente": "Livramento condicional: quanto da pena para primário x reincidente em crime doloso?", "verso": "Primário com bons antecedentes: mais de 1/3. Reincidente em crime doloso: mais da metade.", "explicacao": "CP, art. 83. Hediondos: mais de 2/3, vedado ao reincidente específico."}, {"id": 2000000522, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Em que casos a condenação gera perda do cargo público?", "verso": "Pena de 1 ano ou mais em crime com abuso de poder ou violação de dever para com a Administração; ou pena superior a 4 anos nos demais casos.", "explicacao": "CP, art. 92, I. Não é automática: deve ser declarada na sentença."}, {"id": 2000000523, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Depois de quanto tempo do fim da pena se pode pedir a reabilitação?", "verso": "2 anos.", "explicacao": "CP, art. 94."}, {"id": 2000000524, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "O que é detração penal?", "verso": "Computar na pena o tempo de prisão provisória, no Brasil ou no estrangeiro, e de internação.", "explicacao": "CP, art. 42."}, {"id": 2000000525, "trilha": "policial", "materia": "pen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Qual é a regra para a ação penal no Código Penal?", "verso": "É pública, salvo quando a lei declara expressamente que é privativa do ofendido.", "explicacao": "CP, art. 100."}, {"id": 2000000526, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "pergunta", "frente": "Prazo prescricional para pena máxima superior a 12 anos:", "verso": "20 anos.", "explicacao": "CP, art. 109, I. Mais de 8 até 12: 16 anos; mais de 4 até 8: 12; mais de 2 até 4: 8; de 1 até 2: 4; menos de 1: 3 anos."}, {"id": 2000000527, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "pergunta", "frente": "Prazo prescricional para pena máxima de 1 a 2 anos:", "verso": "4 anos.", "explicacao": "CP, art. 109, V."}, {"id": 2000000528, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "certo_errado", "frente": "Certo ou errado? A prescrição retroativa pode ter por termo inicial data anterior à denúncia ou queixa.", "verso": "Errado.", "explicacao": "CP, art. 110, § 1º (Lei 12.234/2010)."}, {"id": 2000000529, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "pergunta", "frente": "Cite causas que interrompem a prescrição.", "verso": "Recebimento da denúncia ou queixa, pronúncia, decisão confirmatória da pronúncia, sentença ou acórdão condenatórios recorríveis, início ou continuação do cumprimento da pena e reincidência.", "explicacao": "CP, art. 117."}, {"id": 2000000530, "trilha": "policial", "materia": "pen", "assunto": "Princípios", "tipo": "pergunta", "frente": "Quais os requisitos do princípio da insignificância segundo o STF?", "verso": "Mínima ofensividade da conduta, ausência de periculosidade social da ação, reduzido grau de reprovabilidade do comportamento e inexpressividade da lesão jurídica.", "explicacao": "STF, HC 84.412. Exclui a tipicidade material."}, {"id": 2000000531, "trilha": "policial", "materia": "pen", "assunto": "Princípios", "tipo": "certo_errado", "frente": "Certo ou errado? Aplica-se o princípio da insignificância aos crimes contra a mulher no âmbito das relações domésticas.", "verso": "Errado.", "explicacao": "Súmula 589 do STJ."}, {"id": 2000000532, "trilha": "policial", "materia": "pen", "assunto": "Princípios", "tipo": "certo_errado", "frente": "Certo ou errado? O princípio da insignificância é aplicável aos crimes contra a Administração Pública.", "verso": "Errado, segundo o STJ (Súmula 599), com exceção do descaminho em valores baixos.", "explicacao": "Súmula 599 do STJ."}, {"id": 2000000533, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Homicídio culposo: em que casos a pena aumenta de 1/3?", "verso": "Se resulta de inobservância de regra técnica de profissão, se o agente deixa de prestar socorro imediato, não procura diminuir as consequências ou foge para evitar a prisão.", "explicacao": "CP, art. 121, § 4º."}, {"id": 2000000534, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Quando o juiz pode deixar de aplicar a pena no homicídio culposo?", "verso": "Quando as consequências da infração atingirem o próprio agente de forma tão grave que a pena se torne desnecessária (perdão judicial).", "explicacao": "CP, art. 121, § 5º."}, {"id": 2000000535, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Matar policial no exercício da função ou em razão dela é homicídio qualificado?", "verso": "Sim, inclusive quando a vítima é cônjuge, companheiro ou parente até o 3º grau do agente, em razão dessa condição.", "explicacao": "CP, art. 121, § 2º, VII. É crime hediondo."}, {"id": 2000000536, "trilha": "policial", "materia": "pen", "assunto": "Periclitação da vida", "tipo": "pergunta", "frente": "O que é omissão de socorro?", "verso": "Deixar de prestar assistência, quando possível sem risco pessoal, a criança abandonada ou extraviada, pessoa inválida ou ferida, ao desamparo ou em grave e iminente perigo, ou não pedir socorro à autoridade.", "explicacao": "CP, art. 135."}, {"id": 2000000537, "trilha": "policial", "materia": "pen", "assunto": "Periclitação da vida", "tipo": "pergunta", "frente": "O que é maus-tratos (art. 136)?", "verso": "Expor a perigo a vida ou saúde de pessoa sob sua autoridade, guarda ou vigilância, para educação, ensino, tratamento ou custódia, privando de alimentos ou cuidados, sujeitando a trabalho excessivo ou abusando de meios de correção.", "explicacao": "CP, art. 136."}, {"id": 2000000538, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a liberdade", "tipo": "pergunta", "frente": "O que é o crime de perseguição (stalking)?", "verso": "Perseguir alguém, reiteradamente e por qualquer meio, ameaçando sua integridade física ou psicológica, restringindo sua locomoção ou invadindo sua liberdade ou privacidade.", "explicacao": "CP, art. 147-A (Lei 14.132/2021)."}, {"id": 2000000539, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a liberdade", "tipo": "pergunta", "frente": "O que é violência psicológica contra a mulher (art. 147-B)?", "verso": "Causar dano emocional à mulher que a prejudique ou perturbe seu pleno desenvolvimento, ou que vise controlar suas ações, comportamentos, crenças e decisões, por ameaça, constrangimento, humilhação, manipulação, isolamento, entre outros.", "explicacao": "CP, art. 147-B (Lei 14.188/2021)."}, {"id": 2000000540, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a liberdade", "tipo": "pergunta", "frente": "O que é sequestro e cárcere privado?", "verso": "Privar alguém de sua liberdade mediante sequestro ou cárcere privado.", "explicacao": "CP, art. 148. Qualifica-se se a vítima é ascendente, descendente, cônjuge, maior de 60 anos, menor de 18, se dura mais de 15 dias, entre outros."}, {"id": 2000000541, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a liberdade", "tipo": "pergunta", "frente": "Entrar ou permanecer em casa alheia contra a vontade de quem de direito é crime?", "verso": "Sim, violação de domicílio.", "explicacao": "CP, art. 150. Não há crime se a entrada é feita durante o dia, com as formalidades legais, para prisão ou diligência, ou a qualquer hora, quando ali se pratica ou está para se praticar crime (§ 3º)."}, {"id": 2000000542, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a liberdade", "tipo": "pergunta", "frente": "O que é invasão de dispositivo informático?", "verso": "Invadir dispositivo informático de uso alheio, conectado ou não à rede, para obter, adulterar ou destruir dados sem autorização, ou instalar vulnerabilidades.", "explicacao": "CP, art. 154-A (Lei 12.737/2012, “Lei Carolina Dieckmann”)."}, {"id": 2000000543, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Furto de energia elétrica existe?", "verso": "Sim. Equipara-se à coisa móvel a energia elétrica ou qualquer outra que tenha valor econômico.", "explicacao": "CP, art. 155, § 3º."}, {"id": 2000000544, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Furto com emprego de explosivo: qual a pena?", "verso": "Reclusão de 4 a 10 anos e multa. É crime hediondo.", "explicacao": "CP, art. 155, § 4º-A, e Lei 8.072/1990."}, {"id": 2000000545, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Furto de veículo levado para outro Estado ou para o exterior: qual a pena?", "verso": "Reclusão de 3 a 8 anos.", "explicacao": "CP, art. 155, § 5º."}, {"id": 2000000546, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é furto mediante fraude eletrônica e qual a pena?", "verso": "Furto praticado por meio de dispositivo eletrônico ou informático, com ou sem violação de senha, mecanismo de segurança ou programa malicioso. Reclusão de 4 a 8 anos.", "explicacao": "CP, art. 155, § 4º-B (Lei 14.155/2021)."}, {"id": 2000000547, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Cite causas de aumento do roubo de 1/3 até a metade.", "verso": "Concurso de duas ou mais pessoas, vítima em serviço de transporte de valores, subtração de veículo levado a outro Estado ou ao exterior, restrição da liberdade da vítima, subtração de explosivos e emprego de arma branca.", "explicacao": "CP, art. 157, § 2º."}, {"id": 2000000548, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é fraude eletrônica no estelionato e qual a pena?", "verso": "Estelionato com informações fornecidas pela vítima ou terceiro induzido a erro por redes sociais, contatos telefônicos, e-mail fraudulento ou meio semelhante. Reclusão de 4 a 8 anos.", "explicacao": "CP, art. 171, § 2º-A (Lei 14.155/2021)."}, {"id": 2000000549, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Quando o falso é absorvido pelo estelionato?", "verso": "Quando se exaure no estelionato, sem mais potencialidade lesiva.", "explicacao": "Súmula 17 do STJ."}, {"id": 2000000550, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Existe receptação culposa?", "verso": "Sim: adquirir ou receber coisa que, pela natureza, desproporção entre valor e preço ou condição de quem oferece, deve presumir-se obtida por meio criminoso.", "explicacao": "CP, art. 180, § 3º."}, {"id": 2000000551, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é receptação qualificada?", "verso": "A praticada no exercício de atividade comercial ou industrial, com coisa que deve saber ser produto de crime. Reclusão de 3 a 8 anos.", "explicacao": "CP, art. 180, § 1º."}, {"id": 2000000552, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é dano qualificado?", "verso": "Dano com violência ou grave ameaça, com emprego de substância inflamável ou explosiva, contra patrimônio público, por motivo egoístico ou com prejuízo considerável.", "explicacao": "CP, art. 163, parágrafo único."}, {"id": 2000000553, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a dignidade sexual", "tipo": "pergunta", "frente": "O que é importunação sexual?", "verso": "Praticar contra alguém, sem sua anuência, ato libidinoso com o objetivo de satisfazer a própria lascívia ou a de terceiro. Reclusão de 1 a 5 anos.", "explicacao": "CP, art. 215-A (Lei 13.718/2018). Ex.: assédio em transporte público."}, {"id": 2000000554, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a dignidade sexual", "tipo": "pergunta", "frente": "O que é assédio sexual?", "verso": "Constranger alguém para obter vantagem ou favorecimento sexual, prevalecendo-se da condição de superior hierárquico ou ascendência inerentes ao emprego, cargo ou função.", "explicacao": "CP, art. 216-A."}, {"id": 2000000555, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a dignidade sexual", "tipo": "pergunta", "frente": "Qual a ação penal nos crimes contra a dignidade sexual?", "verso": "Pública incondicionada.", "explicacao": "CP, art. 225 (Lei 13.718/2018)."}, {"id": 2000000556, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a dignidade sexual", "tipo": "pergunta", "frente": "Divulgar, sem consentimento, cena de sexo, nudez ou pornografia, ou cena de estupro, é crime?", "verso": "Sim. Reclusão de 1 a 5 anos, aumentada se há relação íntima de afeto com a vítima ou fim de vingança.", "explicacao": "CP, art. 218-C."}, {"id": 2000000557, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a paz pública", "tipo": "pares", "frente": "Associação criminosa x milícia privada.", "verso": "Associação criminosa: 3 ou mais pessoas para cometer crimes (art. 288). Milícia privada: constituir, organizar, integrar ou custear organização paramilitar, milícia, grupo ou esquadrão para praticar crimes do CP (art. 288-A).", "explicacao": "Associação: reclusão de 1 a 3 anos. Milícia: 4 a 8 anos."}, {"id": 2000000558, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a fé pública", "tipo": "pares", "frente": "Falsidade material x falsidade ideológica.", "verso": "Material: o documento é forjado ou alterado na forma (arts. 297 e 298). Ideológica: o documento é verdadeiro na forma, mas o conteúdo é falso (art. 299).", "explicacao": "Ex.: carteira de identidade forjada (material) x declaração falsa num documento autêntico (ideológica)."}, {"id": 2000000559, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a fé pública", "tipo": "pergunta", "frente": "Usar documento falso é crime?", "verso": "Sim, com a mesma pena da falsificação ou alteração do documento usado.", "explicacao": "CP, art. 304."}, {"id": 2000000560, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a fé pública", "tipo": "certo_errado", "frente": "Certo ou errado? Atribuir-se falsa identidade perante a polícia para evitar a prisão é atípico, por ser autodefesa.", "verso": "Errado. É crime, ainda que em situação de autodefesa.", "explicacao": "Súmula 522 do STJ (CP, art. 307)."}, {"id": 2000000561, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a fé pública", "tipo": "pergunta", "frente": "Adulterar placa ou chassi de veículo é crime?", "verso": "Sim: adulteração de sinal identificador de veículo automotor, reclusão de 3 a 6 anos.", "explicacao": "CP, art. 311."}, {"id": 2000000562, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Qual a pena da corrupção ativa?", "verso": "Reclusão de 2 a 12 anos e multa.", "explicacao": "CP, art. 333. A mesma pena da corrupção passiva (art. 317)."}, {"id": 2000000563, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Descaminho x contrabando.", "verso": "Descaminho: iludir o pagamento de imposto devido pela entrada ou saída de mercadoria permitida. Contrabando: importar ou exportar mercadoria proibida.", "explicacao": "CP, arts. 334 e 334-A."}, {"id": 2000000564, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é advocacia administrativa?", "verso": "Patrocinar, direta ou indiretamente, interesse privado perante a Administração, valendo-se da qualidade de funcionário.", "explicacao": "CP, art. 321."}, {"id": 2000000565, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "No falso testemunho, quando o fato deixa de ser punível?", "verso": "Se, antes da sentença no processo em que ocorreu o ilícito, o agente se retrata ou declara a verdade.", "explicacao": "CP, art. 342, § 2º."}, {"id": 2000000566, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é coação no curso do processo?", "verso": "Usar de violência ou grave ameaça contra autoridade, parte ou quem intervém em processo, inquérito ou juízo arbitral, para favorecer interesse próprio ou alheio.", "explicacao": "CP, art. 344."}, {"id": 2000000567, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Favorecimento pessoal x favorecimento real.", "verso": "Pessoal: auxiliar autor de crime a subtrair-se à ação da autoridade (art. 348). Real: prestar auxílio para tornar seguro o proveito do crime (art. 349).", "explicacao": "Se quem presta o favorecimento pessoal é ascendente, descendente, cônjuge ou irmão do criminoso, fica isento de pena."}, {"id": 2000000568, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Ingressar com celular em presídio sem autorização é crime?", "verso": "Sim: ingressar, promover, intermediar, auxiliar ou facilitar a entrada de aparelho de comunicação em estabelecimento prisional. Detenção de 3 meses a 1 ano.", "explicacao": "CP, art. 349-A. Para o diretor que deixa de impedir, art. 319-A."}, {"id": 2000000569, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é exercício arbitrário das próprias razões?", "verso": "Fazer justiça pelas próprias mãos para satisfazer pretensão, embora legítima, salvo quando a lei permite.", "explicacao": "CP, art. 345."}, {"id": 2000000570, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é inserção de dados falsos em sistema de informações?", "verso": "Funcionário autorizado inserir ou facilitar a inserção de dados falsos, alterar ou excluir dados corretos nos sistemas da Administração para obter vantagem ou causar dano.", "explicacao": "CP, art. 313-A (peculato eletrônico)."}, {"id": 2000000571, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Facilitar ou promover a fuga de pessoa legalmente presa é crime?", "verso": "Sim. A pena é maior se o crime for praticado por quem tem a custódia ou guarda do preso.", "explicacao": "CP, art. 351."}, {"id": 2000000572, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Cite providências do delegado logo que souber da infração (art. 6º).", "verso": "Ir ao local e preservar o estado das coisas até a perícia, apreender objetos após liberação pelos peritos, colher provas, ouvir o ofendido e o indiciado, fazer reconhecimentos e acareações, determinar exame de corpo de delito, identificar o indiciado e juntar sua folha de antecedentes.", "explicacao": "CPP, art. 6º."}, {"id": 2000000573, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "A reprodução simulada dos fatos pode ser feita sempre?", "verso": "Não, se contrariar a moralidade ou a ordem pública. E o investigado não é obrigado a participar.", "explicacao": "CPP, art. 7º, e princípio da não autoincriminação."}, {"id": 2000000574, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O ofendido pode requerer diligências ao delegado?", "verso": "Sim, e o delegado decide se as realiza (salvo o exame de corpo de delito, que não pode ser negado).", "explicacao": "CPP, arts. 14 e 184."}, {"id": 2000000575, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Instaurado o inquérito, o delegado pode requisitar dados cadastrais da vítima ou suspeito sem ordem judicial em quais crimes?", "verso": "Em crimes como sequestro e cárcere privado, redução à condição análoga à de escravo, tráfico de pessoas e extorsão com restrição da liberdade, entre outros.", "explicacao": "CPP, art. 13-A."}, {"id": 2000000576, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Até quando a representação pode ser retratada?", "verso": "Até o oferecimento da denúncia.", "explicacao": "CPP, art. 25. Na Lei Maria da Penha, a renúncia só perante o juiz, em audiência, antes do recebimento (art. 16)."}, {"id": 2000000577, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Morto o ofendido, quem pode oferecer queixa ou prosseguir na ação privada?", "verso": "Cônjuge, ascendente, descendente ou irmão (CADI), nessa ordem.", "explicacao": "CPP, art. 31."}, {"id": 2000000578, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "O que é perempção?", "verso": "A perda do direito de prosseguir na ação privada por negligência do querelante (ex.: deixar de promover o andamento por 30 dias seguidos ou não comparecer a ato a que deva estar presente).", "explicacao": "CPP, art. 60."}, {"id": 2000000579, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Ofensa à honra de servidor público em razão da função: quem pode propor a ação?", "verso": "Legitimidade concorrente: o ofendido, por queixa, ou o MP, mediante representação do ofendido.", "explicacao": "Súmula 714 do STF."}, {"id": 2000000580, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Crime contra a honra do Presidente da República: qual a ação penal?", "verso": "Pública condicionada à requisição do Ministro da Justiça.", "explicacao": "CP, art. 145, parágrafo único."}, {"id": 2000000581, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Quais crimes são da Justiça Federal pelo art. 109, IV, da CF?", "verso": "Crimes políticos e infrações em detrimento de bens, serviços ou interesse da União, de suas autarquias ou empresas públicas, excluídas as contravenções e ressalvada a Justiça Militar e Eleitoral.", "explicacao": "CF, art. 109, IV."}, {"id": 2000000582, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Crime federal conexo com crime estadual: quem julga?", "verso": "A Justiça Federal julga os dois.", "explicacao": "Súmula 122 do STJ."}, {"id": 2000000583, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Contravenção penal praticada contra bens da União: quem julga?", "verso": "A Justiça Estadual.", "explicacao": "Súmula 38 do STJ e CF, art. 109, IV."}, {"id": 2000000584, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Crime em que o indígena figura como autor ou vítima: quem julga, em regra?", "verso": "A Justiça Estadual.", "explicacao": "Súmula 140 do STJ. Será federal se envolver disputa sobre direitos indígenas (CF, art. 109, XI)."}, {"id": 2000000585, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Crime contra sociedade de economia mista federal (ex.: Banco do Brasil): quem julga?", "verso": "A Justiça Estadual.", "explicacao": "Súmula 42 do STJ. Empresa pública federal (ex.: Caixa) é Justiça Federal."}, {"id": 2000000586, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Moeda falsa grosseira, incapaz de enganar: que crime e quem julga?", "verso": "Pode configurar estelionato, da competência da Justiça Estadual.", "explicacao": "Súmula 73 do STJ."}, {"id": 2000000587, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pares", "frente": "Tráfico de drogas interno x transnacional: quem julga?", "verso": "Interno: Justiça Estadual. Transnacional: Justiça Federal.", "explicacao": "CF, art. 109, V, e Lei 11.343/2006, art. 70."}, {"id": 2000000588, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "O que é conexão probatória (instrumental)?", "verso": "Quando a prova de uma infração ou de qualquer de suas circunstâncias influi na prova de outra.", "explicacao": "CPP, art. 76, III."}, {"id": 2000000589, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Crime doloso contra a vida de civil praticado por militar estadual: quem julga?", "verso": "O Tribunal do Júri.", "explicacao": "CF, art. 125, § 4º."}, {"id": 2000000590, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Quem julga o Presidente da República por crime comum?", "verso": "O STF, após autorização de 2/3 da Câmara dos Deputados.", "explicacao": "CF, arts. 86 e 102, I, b."}, {"id": 2000000591, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "certo_errado", "frente": "Certo ou errado? O depoimento de policiais não serve como prova por eles terem participado da prisão.", "verso": "Errado. É válido, como o de qualquer testemunha, devendo ser avaliado com as demais provas.", "explicacao": "Jurisprudência do STF e do STJ."}, {"id": 2000000592, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quem pode se recusar a depor como testemunha?", "verso": "Ascendente, descendente, afim em linha reta, cônjuge (mesmo separado), irmão, pai, mãe ou filho adotivo do acusado, salvo se não houver outro modo de obter a prova.", "explicacao": "CPP, art. 206."}, {"id": 2000000593, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quem é proibido de depor?", "verso": "Quem, em razão de função, ministério, ofício ou profissão, deve guardar segredo, salvo se desobrigado pela parte interessada e quiser dar o testemunho.", "explicacao": "CPP, art. 207."}, {"id": 2000000594, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quem depõe sem prestar o compromisso de dizer a verdade?", "verso": "Doentes e deficientes mentais, menores de 14 anos e as pessoas do art. 206 (parentes).", "explicacao": "CPP, art. 208."}, {"id": 2000000595, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quando a busca pessoal dispensa mandado?", "verso": "No caso de prisão, quando houver fundada suspeita de que a pessoa oculta arma ou objetos de crime, ou durante busca domiciliar.", "explicacao": "CPP, art. 244. O STJ exige elementos objetivos para a fundada suspeita."}, {"id": 2000000596, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quem faz a busca pessoal em mulher?", "verso": "Outra mulher, se não importar retardamento ou prejuízo da diligência.", "explicacao": "CPP, art. 249."}, {"id": 2000000597, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Entrada forçada em casa sem mandado, em crime permanente, é lícita quando?", "verso": "Quando amparada em fundadas razões, justificadas depois, que indiquem flagrante dentro da casa.", "explicacao": "STF, Tema 280 (RE 603.616)."}, {"id": 2000000598, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "O que é acareação?", "verso": "Confrontar pessoas cujas declarações divergem sobre fatos ou circunstâncias relevantes.", "explicacao": "CPP, art. 229."}, {"id": 2000000599, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quais as etapas da cadeia de custódia?", "verso": "Reconhecimento, isolamento, fixação, coleta, acondicionamento, transporte, recebimento, processamento, armazenamento e descarte.", "explicacao": "CPP, art. 158-B."}, {"id": 2000000600, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "A captação ambiental depende de quê?", "verso": "De autorização judicial, quando a prova não puder ser feita por outros meios e houver indícios de crime com pena máxima superior a 4 anos.", "explicacao": "Lei 9.296/1996, art. 8º-A (Pacote Anticrime)."}, {"id": 2000000601, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quando o exame necroscópico pode ser feito?", "verso": "Pelo menos 6 horas depois do óbito, salvo se os peritos, pela evidência dos sinais de morte, julgarem que pode ser feito antes.", "explicacao": "CPP, art. 162."}, {"id": 2000000602, "trilha": "policial", "materia": "ppen", "assunto": "Prisão", "tipo": "pares", "frente": "Flagrante facultativo x obrigatório.", "verso": "Facultativo: qualquer do povo pode prender quem esteja em flagrante. Obrigatório: as autoridades policiais e seus agentes devem prender.", "explicacao": "CPP, art. 301."}, {"id": 2000000603, "trilha": "policial", "materia": "ppen", "assunto": "Prisão", "tipo": "pergunta", "frente": "O mandado de prisão pode ser cumprido em qualquer dia e hora?", "verso": "Sim, respeitadas as restrições relativas à inviolabilidade do domicílio.", "explicacao": "CPP, art. 283, § 2º."}, {"id": 2000000604, "trilha": "policial", "materia": "ppen", "assunto": "Prisão", "tipo": "pergunta", "frente": "Em que crimes cabe a prisão preventiva (art. 313)?", "verso": "Crimes dolosos com pena máxima superior a 4 anos; reincidente em crime doloso; violência doméstica para garantir medidas protetivas; ou dúvida sobre a identidade civil.", "explicacao": "CPP, art. 313."}, {"id": 2000000605, "trilha": "policial", "materia": "ppen", "assunto": "Prisão", "tipo": "certo_errado", "frente": "Certo ou errado? A preventiva pode ser decretada para antecipar o cumprimento da pena.", "verso": "Errado.", "explicacao": "CPP, art. 313, § 2º."}, {"id": 2000000606, "trilha": "policial", "materia": "ppen", "assunto": "Prisão", "tipo": "pergunta", "frente": "Cabe preventiva em crime culposo?", "verso": "Não. O art. 313 exige crime doloso (salvo a hipótese de dúvida sobre a identidade).", "explicacao": "CPP, art. 313."}, {"id": 2000000607, "trilha": "policial", "materia": "ppen", "assunto": "Prisão", "tipo": "pergunta", "frente": "Qual o valor da fiança para crime com pena máxima de até 4 anos?", "verso": "De 1 a 100 salários mínimos.", "explicacao": "CPP, art. 325, I. Acima de 4 anos: de 10 a 200 salários mínimos (podendo ser reduzida ou aumentada)."}, {"id": 2000000608, "trilha": "policial", "materia": "ppen", "assunto": "Prisão", "tipo": "pares", "frente": "Quebramento x perda da fiança.", "verso": "Quebramento: o afiançado descumpre obrigações (ex.: não comparece a ato); perde metade do valor. Perda: o condenado não se apresenta para cumprir a pena; perde o valor total.", "explicacao": "CPP, arts. 341, 343 e 344."}, {"id": 2000000609, "trilha": "policial", "materia": "ppen", "assunto": "Prisão", "tipo": "pares", "frente": "Relaxamento x liberdade provisória x revogação da prisão.", "verso": "Relaxamento: a prisão é ilegal. Liberdade provisória: a prisão em flagrante foi legal, mas não é necessária. Revogação: a preventiva deixou de ser necessária.", "explicacao": "CF, art. 5º, LXV e LXVI, e CPP, art. 316."}, {"id": 2000000610, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Qual o prazo da resposta à acusação?", "verso": "10 dias após a citação.", "explicacao": "CPP, art. 396."}, {"id": 2000000611, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Em que casos o juiz absolve sumariamente após a resposta?", "verso": "Excludente de ilicitude manifesta, excludente de culpabilidade manifesta (salvo inimputabilidade), fato evidentemente atípico ou extinção da punibilidade.", "explicacao": "CPP, art. 397."}, {"id": 2000000612, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Como pode ser a citação quando o réu se oculta?", "verso": "Por hora certa.", "explicacao": "CPP, art. 362."}, {"id": 2000000613, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Réu preso: como é citado?", "verso": "Pessoalmente.", "explicacao": "CPP, art. 360."}, {"id": 2000000614, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Quais os fundamentos de absolvição do art. 386?", "verso": "Inexistência do fato, falta de prova do fato, fato não constitui crime, prova de que o réu não concorreu, falta de prova de que concorreu, excludentes de crime ou isenção de pena (ou dúvida sobre elas) e prova insuficiente para condenar.", "explicacao": "CPP, art. 386."}, {"id": 2000000615, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Quantos jurados formam o Conselho de Sentença?", "verso": "7, sorteados entre os 25 convocados.", "explicacao": "CPP, arts. 433 e 447."}, {"id": 2000000616, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Quantas recusas imotivadas cada parte pode fazer no júri?", "verso": "Até 3.", "explicacao": "CPP, art. 468."}, {"id": 2000000617, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "O que é desaforamento?", "verso": "Levar o julgamento para outra comarca por interesse da ordem pública, dúvida sobre a imparcialidade do júri, segurança do acusado ou demora excessiva.", "explicacao": "CPP, arts. 427 e 428."}, {"id": 2000000618, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Qual a pergunta obrigatória da absolvição genérica no júri?", "verso": "“O jurado absolve o acusado?”", "explicacao": "CPP, art. 483, § 2º."}, {"id": 2000000619, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Qual a idade mínima para ser jurado?", "verso": "18 anos, cidadão de notória idoneidade.", "explicacao": "CPP, art. 436."}, {"id": 2000000620, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "pergunta", "frente": "Qual o prazo dos embargos de declaração no processo penal?", "verso": "2 dias.", "explicacao": "CPP, art. 619."}, {"id": 2000000621, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "pergunta", "frente": "Cite hipóteses de recurso em sentido estrito.", "verso": "Decisão que não recebe a denúncia, que conclui pela incompetência do juízo, que concede, nega ou arbitra fiança, que indefere ou revoga a preventiva, que decreta a extinção da punibilidade e que pronuncia o réu.", "explicacao": "CPP, art. 581."}, {"id": 2000000622, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "pergunta", "frente": "Quem pode impetrar habeas corpus?", "verso": "Qualquer pessoa, em seu favor ou de outrem, e o Ministério Público. Não precisa de advogado.", "explicacao": "CPP, art. 654."}, {"id": 2000000623, "trilha": "policial", "materia": "ppen", "assunto": "Nulidades", "tipo": "pares", "frente": "Nulidade absoluta x relativa.", "verso": "Absoluta: viola norma de interesse público, pode ser alegada a qualquer tempo, prejuízo presumido. Relativa: interesse da parte, deve ser alegada no momento oportuno e exige prova do prejuízo.", "explicacao": "CPP, arts. 563 a 573."}, {"id": 2000000624, "trilha": "policial", "materia": "ppen", "assunto": "Nulidades", "tipo": "lacuna", "frente": "Nenhum ato será declarado nulo se da nulidade não resultar ____ para a acusação ou para a defesa.", "verso": "prejuízo", "explicacao": "CPP, art. 563 (pas de nullité sans grief)."}, {"id": 2000000625, "trilha": "policial", "materia": "ppen", "assunto": "Nulidades", "tipo": "pergunta", "frente": "Falta de defesa x deficiência da defesa: qual anula o processo?", "verso": "A falta de defesa é nulidade absoluta. A deficiência só anula se houver prova de prejuízo.", "explicacao": "Súmula 523 do STF."}, {"id": 2000000626, "trilha": "policial", "materia": "ppen", "assunto": "Medidas assecuratórias", "tipo": "pares", "frente": "Sequestro x arresto x hipoteca legal.", "verso": "Sequestro: bens adquiridos com os proventos do crime. Arresto: bens lícitos do acusado, para garantir reparação e custas. Hipoteca legal: sobre imóveis do acusado, com a mesma finalidade.", "explicacao": "CPP, arts. 125 a 144."}, {"id": 2000000627, "trilha": "policial", "materia": "ppen", "assunto": "Apreensão", "tipo": "pergunta", "frente": "Coisas apreendidas podem ser devolvidas antes do trânsito em julgado?", "verso": "Não, enquanto interessarem ao processo.", "explicacao": "CPP, art. 118."}, {"id": 2000000628, "trilha": "policial", "materia": "ppen", "assunto": "Incidentes", "tipo": "pergunta", "frente": "Quando se instaura o incidente de insanidade mental?", "verso": "Quando houver dúvida sobre a integridade mental do acusado, de ofício ou a requerimento, inclusive no inquérito, por representação do delegado ao juiz.", "explicacao": "CPP, art. 149."}, {"id": 2000000629, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "Na Lei 9.099, quais crimes passaram a depender de representação?", "verso": "Lesão corporal leve e lesão corporal culposa.", "explicacao": "Lei 9.099/1995, art. 88. Não se aplica à violência doméstica contra a mulher."}, {"id": 2000000630, "trilha": "policial", "materia": "ppen", "assunto": "ANPP", "tipo": "pergunta", "frente": "O ANPP cabe em violência doméstica contra a mulher?", "verso": "Não.", "explicacao": "CPP, art. 28-A, § 2º, IV."}, {"id": 2000000631, "trilha": "policial", "materia": "ppen", "assunto": "ANPP", "tipo": "pergunta", "frente": "Cabe ANPP quando é cabível a transação penal?", "verso": "Não. A transação tem preferência.", "explicacao": "CPP, art. 28-A, § 2º, I."}, {"id": 2000000632, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O valor mínimo de indenização à vítima pode ser fixado na sentença penal?", "verso": "Sim. O juiz fixa um valor mínimo para reparação dos danos, sem prejuízo da liquidação no cível.", "explicacao": "CPP, art. 387, IV."}, {"id": 2000000633, "trilha": "policial", "materia": "ppen", "assunto": "Identificação", "tipo": "pergunta", "frente": "A identificação do perfil genético do condenado é obrigatória para quem?", "verso": "Condenados por crime doloso praticado com violência grave contra a pessoa, crimes contra a vida, contra a liberdade sexual e crimes sexuais contra vulnerável.", "explicacao": "LEP, art. 9º-A. A recusa é falta grave."}, {"id": 2000000634, "trilha": "policial", "materia": "ppen", "assunto": "Interrogatório", "tipo": "pergunta", "frente": "O interrogatório por videoconferência é a regra?", "verso": "Não. É excepcional, por decisão fundamentada, para prevenir risco à segurança, viabilizar a participação do réu, impedir influência em testemunha ou por gravíssima questão de ordem pública.", "explicacao": "CPP, art. 185, § 2º."}, {"id": 2000000635, "trilha": "policial", "materia": "ppen", "assunto": "Interrogatório", "tipo": "pergunta", "frente": "Quais as duas partes do interrogatório?", "verso": "Sobre a pessoa do acusado e sobre os fatos.", "explicacao": "CPP, art. 187."}, {"id": 2000000636, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "lacuna", "frente": "É livre a manifestação do pensamento, sendo vedado o ____.", "verso": "anonimato", "explicacao": "CF, art. 5º, IV."}, {"id": 2000000637, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "O que garante o direito de resposta?", "verso": "Resposta proporcional ao agravo, além de indenização por dano material, moral ou à imagem.", "explicacao": "CF, art. 5º, V."}, {"id": 2000000638, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "O que acontece com quem invoca escusa de consciência para fugir de obrigação legal a todos imposta?", "verso": "Pode ter direitos políticos restringidos se recusar também a prestação alternativa fixada em lei.", "explicacao": "CF, arts. 5º, VIII, e 15, IV."}, {"id": 2000000639, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A expressão da atividade intelectual, artística e de comunicação depende de licença?", "verso": "Não. É livre, independentemente de censura ou licença.", "explicacao": "CF, art. 5º, IX."}, {"id": 2000000640, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Ninguém pode ser compelido a associar-se. E a permanecer associado?", "verso": "Também não.", "explicacao": "CF, art. 5º, XX."}, {"id": 2000000641, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Em tempo de paz, qualquer pessoa pode entrar, permanecer ou sair do território nacional com seus bens?", "verso": "Sim, nos termos da lei.", "explicacao": "CF, art. 5º, XV."}, {"id": 2000000642, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Requisição administrativa de propriedade particular: quando cabe e como indeniza?", "verso": "Em caso de iminente perigo público; indenização ulterior, se houver dano.", "explicacao": "CF, art. 5º, XXV."}, {"id": 2000000643, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "O direito de petição e a obtenção de certidões em repartições públicas dependem de taxa?", "verso": "Não. São assegurados independentemente do pagamento de taxas.", "explicacao": "CF, art. 5º, XXXIV."}, {"id": 2000000644, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "lacuna", "frente": "A lei não excluirá da apreciação do Poder Judiciário lesão ou ____ a direito.", "verso": "ameaça", "explicacao": "CF, art. 5º, XXXV (inafastabilidade da jurisdição)."}, {"id": 2000000645, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A Constituição admite juízo ou tribunal de exceção?", "verso": "Não.", "explicacao": "CF, art. 5º, XXXVII."}, {"id": 2000000646, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A pena pode passar da pessoa do condenado?", "verso": "Não. Mas a obrigação de reparar o dano e a decretação do perdimento de bens podem ser estendidas aos sucessores, até o limite do patrimônio transferido.", "explicacao": "CF, art. 5º, XLV."}, {"id": 2000000647, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Quais penas a lei pode adotar, segundo a Constituição?", "verso": "Privação ou restrição da liberdade, perda de bens, multa, prestação social alternativa e suspensão ou interdição de direitos.", "explicacao": "CF, art. 5º, XLVI."}, {"id": 2000000648, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Que garantia a Constituição dá às presidiárias com filhos?", "verso": "Condições para que possam permanecer com seus filhos durante o período de amamentação.", "explicacao": "CF, art. 5º, L."}, {"id": 2000000649, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Estrangeiro pode ser extraditado por crime político ou de opinião?", "verso": "Não.", "explicacao": "CF, art. 5º, LII."}, {"id": 2000000650, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "lacuna", "frente": "Ninguém será considerado culpado até o ____ de sentença penal condenatória.", "verso": "trânsito em julgado", "explicacao": "CF, art. 5º, LVII (presunção de inocência)."}, {"id": 2000000651, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "O que garante o art. 5º, LV?", "verso": "Contraditório e ampla defesa, com os meios e recursos a ela inerentes, aos litigantes em processo judicial ou administrativo e aos acusados em geral.", "explicacao": "CF, art. 5º, LV."}, {"id": 2000000652, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A prisão de qualquer pessoa deve ser comunicada a quem?", "verso": "Imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada.", "explicacao": "CF, art. 5º, LXII."}, {"id": 2000000653, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A prisão ilegal deve ser:", "verso": "Imediatamente relaxada pela autoridade judiciária.", "explicacao": "CF, art. 5º, LXV."}, {"id": 2000000654, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Quem tem direito à assistência jurídica integral e gratuita?", "verso": "Quem comprovar insuficiência de recursos.", "explicacao": "CF, art. 5º, LXXIV. Prestada pela Defensoria Pública (art. 134)."}, {"id": 2000000655, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "O Estado indeniza quem?", "verso": "O condenado por erro judiciário e quem ficar preso além do tempo fixado na sentença.", "explicacao": "CF, art. 5º, LXXV."}, {"id": 2000000656, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A proteção de dados pessoais é direito fundamental expresso?", "verso": "Sim, inclusive nos meios digitais.", "explicacao": "CF, art. 5º, LXXIX (EC 115/2022)."}, {"id": 2000000657, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "As normas definidoras de direitos fundamentais têm que aplicabilidade?", "verso": "Aplicação imediata.", "explicacao": "CF, art. 5º, § 1º."}, {"id": 2000000658, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Que garantia o art. 5º, LXXVIII, assegura?", "verso": "A razoável duração do processo e os meios que garantam a celeridade de sua tramitação.", "explicacao": "CF, art. 5º, LXXVIII (EC 45/2004)."}, {"id": 2000000659, "trilha": "policial", "materia": "const", "assunto": "Nacionalidade", "tipo": "pergunta", "frente": "Quem é brasileiro nato?", "verso": "Nascidos no Brasil (ainda que de pais estrangeiros, desde que não a serviço de seu país); nascidos no exterior de pai ou mãe brasileiros a serviço do Brasil; ou nascidos no exterior de pai ou mãe brasileiros registrados em repartição brasileira ou que venham residir no Brasil e optem pela nacionalidade.", "explicacao": "CF, art. 12, I."}, {"id": 2000000660, "trilha": "policial", "materia": "const", "assunto": "Nacionalidade", "tipo": "pares", "frente": "Naturalização: originário de país de língua portuguesa x demais estrangeiros.", "verso": "Língua portuguesa: 1 ano ininterrupto de residência e idoneidade moral. Demais: mais de 15 anos ininterruptos de residência e sem condenação penal, se requererem.", "explicacao": "CF, art. 12, II."}, {"id": 2000000661, "trilha": "policial", "materia": "const", "assunto": "Nacionalidade", "tipo": "pergunta", "frente": "Em que casos o brasileiro perde a nacionalidade, após a EC 131/2023?", "verso": "Cancelamento da naturalização por sentença judicial, por fraude ou atentado contra a ordem constitucional e o Estado Democrático; ou pedido expresso perante autoridade brasileira.", "explicacao": "CF, art. 12, § 4º."}, {"id": 2000000662, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "Quem é inelegível pela Constituição de forma absoluta?", "verso": "Os inalistáveis e os analfabetos.", "explicacao": "CF, art. 14, § 4º."}, {"id": 2000000663, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "Quem não pode se alistar como eleitor?", "verso": "Os estrangeiros e, durante o serviço militar obrigatório, os conscritos.", "explicacao": "CF, art. 14, § 2º."}, {"id": 2000000664, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "Lei que altera o processo eleitoral entra em vigor quando?", "verso": "Na data de sua publicação, mas não se aplica à eleição que ocorra até 1 ano da data de sua vigência.", "explicacao": "CF, art. 16 (anterioridade eleitoral)."}, {"id": 2000000665, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "Em que casos há perda ou suspensão dos direitos políticos?", "verso": "Cancelamento da naturalização, incapacidade civil absoluta, condenação criminal transitada em julgado (enquanto durarem seus efeitos), recusa de obrigação a todos imposta e improbidade administrativa.", "explicacao": "CF, art. 15."}, {"id": 2000000666, "trilha": "policial", "materia": "const", "assunto": "Organização do Estado", "tipo": "pergunta", "frente": "Quem tem competência privativa para legislar sobre direito penal e processual?", "verso": "A União.", "explicacao": "CF, art. 22, I."}, {"id": 2000000667, "trilha": "policial", "materia": "const", "assunto": "Organização do Estado", "tipo": "pergunta", "frente": "Direito penitenciário: de quem é a competência legislativa?", "verso": "Concorrente: União, Estados e DF.", "explicacao": "CF, art. 24, I."}, {"id": 2000000668, "trilha": "policial", "materia": "const", "assunto": "Organização do Estado", "tipo": "pergunta", "frente": "O Distrito Federal pode ser dividido em Municípios?", "verso": "Não.", "explicacao": "CF, art. 32."}, {"id": 2000000669, "trilha": "policial", "materia": "const", "assunto": "Organização do Estado", "tipo": "pergunta", "frente": "Quem decreta a intervenção federal?", "verso": "O Presidente da República.", "explicacao": "CF, art. 84, X. O decreto é submetido ao Congresso em 24 horas (art. 36, § 1º)."}, {"id": 2000000670, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "certo_errado", "frente": "Certo ou errado? Policiais civis podem fazer greve.", "verso": "Errado. O STF proibiu o exercício do direito de greve por servidores da segurança pública.", "explicacao": "STF, ARE 654.432 (Tema 541)."}, {"id": 2000000671, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Qual a idade da aposentadoria compulsória do servidor?", "verso": "75 anos.", "explicacao": "CF, art. 40, § 1º, II, e LC 152/2015."}, {"id": 2000000672, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Quais as sanções da improbidade previstas na Constituição?", "verso": "Suspensão dos direitos políticos, perda da função pública, indisponibilidade dos bens e ressarcimento ao erário.", "explicacao": "CF, art. 37, § 4º."}, {"id": 2000000673, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "A ação de ressarcimento ao erário por ato doloso de improbidade prescreve?", "verso": "Não. É imprescritível.", "explicacao": "STF, Tema 897 (RE 852.475)."}, {"id": 2000000674, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Qual o teto remuneratório no serviço público?", "verso": "O subsídio mensal dos Ministros do STF.", "explicacao": "CF, art. 37, XI. Nos Estados há subtetos."}, {"id": 2000000675, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pares", "frente": "Imunidade material x imunidade formal dos parlamentares.", "verso": "Material: são invioláveis, civil e penalmente, por opiniões, palavras e votos. Formal: só podem ser presos em flagrante de crime inafiançável, e a Casa pode sustar o andamento da ação penal.", "explicacao": "CF, art. 53."}, {"id": 2000000676, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Deputado preso em flagrante de crime inafiançável: o que acontece?", "verso": "Os autos vão em 24 horas à Casa respectiva, que decide sobre a prisão pelo voto da maioria de seus membros.", "explicacao": "CF, art. 53, § 2º."}, {"id": 2000000677, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quem processa e julga o Presidente nos crimes de responsabilidade?", "verso": "O Senado Federal, após autorização de 2/3 da Câmara.", "explicacao": "CF, arts. 51, I, e 52, I."}, {"id": 2000000678, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quais os requisitos da iniciativa popular de lei federal?", "verso": "Assinatura de no mínimo 1% do eleitorado nacional, distribuído por pelo menos 5 Estados, com não menos de 0,3% dos eleitores de cada um.", "explicacao": "CF, art. 61, § 2º."}, {"id": 2000000679, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quem auxilia o Congresso no controle externo?", "verso": "O Tribunal de Contas da União.", "explicacao": "CF, art. 71."}, {"id": 2000000680, "trilha": "policial", "materia": "const", "assunto": "Poder Executivo", "tipo": "pergunta", "frente": "O Presidente pode ser responsabilizado, no mandato, por atos estranhos às suas funções?", "verso": "Não. Tem imunidade temporária quanto a esses atos.", "explicacao": "CF, art. 86, § 4º."}, {"id": 2000000681, "trilha": "policial", "materia": "const", "assunto": "Poder Executivo", "tipo": "pergunta", "frente": "Recebida a denúncia contra o Presidente por crime comum, o que acontece?", "verso": "Ele fica suspenso de suas funções por até 180 dias.", "explicacao": "CF, art. 86, § 1º, I, e § 2º."}, {"id": 2000000682, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quantos membros tem o Conselho Nacional de Justiça?", "verso": "15 membros, com mandato de 2 anos.", "explicacao": "CF, art. 103-B. É presidido pelo Presidente do STF."}, {"id": 2000000683, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "O que é o quinto constitucional?", "verso": "Um quinto das vagas dos tribunais (TRFs e TJs) é preenchido por membros do MP e advogados com mais de 10 anos de carreira ou atividade.", "explicacao": "CF, art. 94."}, {"id": 2000000684, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quantos ministros tem o STJ?", "verso": "No mínimo 33.", "explicacao": "CF, art. 104."}, {"id": 2000000685, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "O que a parte precisa demonstrar no recurso extraordinário?", "verso": "A repercussão geral das questões constitucionais discutidas.", "explicacao": "CF, art. 102, § 3º."}, {"id": 2000000686, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quem julga os militares dos Estados nos crimes militares?", "verso": "A Justiça Militar estadual.", "explicacao": "CF, art. 125, § 4º, ressalvada a competência do júri quando a vítima for civil."}, {"id": 2000000687, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Além de combate a incêndios, qual a atribuição constitucional dos corpos de bombeiros militares?", "verso": "A execução de atividades de defesa civil.", "explicacao": "CF, art. 144, § 5º."}, {"id": 2000000688, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "A segurança viária é atribuição de quem?", "verso": "Dos órgãos ou entidades executivos e seus agentes de trânsito, estruturados em carreira, no âmbito dos Estados, DF e Municípios.", "explicacao": "CF, art. 144, § 10 (EC 82/2014)."}, {"id": 2000000689, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Quem dirige a polícia civil?", "verso": "Delegados de polícia de carreira.", "explicacao": "CF, art. 144, § 4º."}, {"id": 2000000690, "trilha": "policial", "materia": "const", "assunto": "Defesa do Estado", "tipo": "pares", "frente": "Estado de sítio: duração em comoção grave x guerra.", "verso": "Comoção grave ou ineficácia do estado de defesa: até 30 dias por vez, prorrogáveis. Guerra ou agressão armada estrangeira: por todo o tempo que perdurar a guerra.", "explicacao": "CF, art. 138, § 1º."}, {"id": 2000000691, "trilha": "policial", "materia": "const", "assunto": "Defesa do Estado", "tipo": "pergunta", "frente": "Qual a missão das Forças Armadas?", "verso": "Defesa da Pátria, garantia dos Poderes constitucionais e, por iniciativa de qualquer destes, da lei e da ordem.", "explicacao": "CF, art. 142."}, {"id": 2000000692, "trilha": "policial", "materia": "const", "assunto": "Direitos sociais", "tipo": "pergunta", "frente": "Qual a idade mínima para trabalhar no Brasil?", "verso": "16 anos, salvo como aprendiz, a partir de 14. Trabalho noturno, perigoso ou insalubre só a partir de 18.", "explicacao": "CF, art. 7º, XXXIII."}, {"id": 2000000693, "trilha": "policial", "materia": "const", "assunto": "Funções essenciais", "tipo": "pergunta", "frente": "Quais os princípios institucionais do Ministério Público?", "verso": "Unidade, indivisibilidade e independência funcional.", "explicacao": "CF, art. 127, § 1º."}, {"id": 2000000694, "trilha": "policial", "materia": "const", "assunto": "Funções essenciais", "tipo": "pergunta", "frente": "Qual a função da Defensoria Pública?", "verso": "Orientação jurídica, promoção dos direitos humanos e defesa, em todos os graus, dos direitos individuais e coletivos dos necessitados, de forma integral e gratuita.", "explicacao": "CF, art. 134."}, {"id": 2000000695, "trilha": "policial", "materia": "const", "assunto": "Princípios fundamentais", "tipo": "pergunta", "frente": "Cite princípios que regem o Brasil nas relações internacionais.", "verso": "Independência nacional, prevalência dos direitos humanos, autodeterminação dos povos, não intervenção, igualdade entre os Estados, defesa da paz, solução pacífica dos conflitos, repúdio ao terrorismo e ao racismo, cooperação e concessão de asilo político.", "explicacao": "CF, art. 4º."}, {"id": 2000000696, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Em quanto tempo prescrevem as penas do porte para consumo (art. 28)?", "verso": "2 anos.", "explicacao": "Lei 11.343/2006, art. 30."}, {"id": 2000000697, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Semear, cultivar ou colher plantas que se constituam em matéria-prima de droga, para tráfico, é crime?", "verso": "Sim, com a mesma pena do tráfico (5 a 15 anos).", "explicacao": "Lei 11.343/2006, art. 33, § 1º, II. Para consumo pessoal, aplica-se o art. 28, § 1º."}, {"id": 2000000698, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Induzir, instigar ou auxiliar alguém ao uso indevido de droga é crime?", "verso": "Sim: detenção de 1 a 3 anos e multa.", "explicacao": "Lei 11.343/2006, art. 33, § 2º. O STF admite a “Marcha da Maconha” como liberdade de expressão (ADI 4.274)."}, {"id": 2000000699, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Qual a pena de quem financia ou custeia o tráfico?", "verso": "Reclusão de 8 a 20 anos e multa.", "explicacao": "Lei 11.343/2006, art. 36."}, {"id": 2000000700, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Colaborar como informante com grupo destinado ao tráfico é crime?", "verso": "Sim: reclusão de 2 a 6 anos e multa.", "explicacao": "Lei 11.343/2006, art. 37."}, {"id": 2000000701, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "O que o juiz considera com preponderância na fixação da pena do tráfico?", "verso": "A natureza e a quantidade da substância, a personalidade e a conduta social do agente.", "explicacao": "Lei 11.343/2006, art. 42."}, {"id": 2000000702, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Qual o benefício para quem colabora voluntariamente na identificação dos coautores e recuperação do produto do crime?", "verso": "Redução da pena de 1/3 a 2/3.", "explicacao": "Lei 11.343/2006, art. 41."}, {"id": 2000000703, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "O agente dependente que, ao tempo do crime, era inteiramente incapaz de entender o caráter ilícito é punido?", "verso": "Não. É isento de pena e encaminhado a tratamento.", "explicacao": "Lei 11.343/2006, art. 45."}, {"id": 2000000704, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Para incidir a causa de aumento da transnacionalidade, é preciso a droga cruzar a fronteira?", "verso": "Não. Basta a prova de que a droga se destinava ao exterior ou dele provinha.", "explicacao": "Súmula 607 do STJ."}, {"id": 2000000705, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Conduzir embarcação ou aeronave após consumir droga, expondo outros a dano, é crime?", "verso": "Sim: detenção de 6 meses a 3 anos, além da apreensão do veículo e cassação da habilitação.", "explicacao": "Lei 11.343/2006, art. 39."}, {"id": 2000000706, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Em que âmbitos se configura a violência doméstica e familiar contra a mulher?", "verso": "No âmbito da unidade doméstica, no âmbito da família e em qualquer relação íntima de afeto.", "explicacao": "Lei 11.340/2006, art. 5º."}, {"id": 2000000707, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Cite medidas protetivas que obrigam o agressor.", "verso": "Suspensão da posse ou restrição do porte de armas, afastamento do lar, proibição de aproximação e de contato, restrição de visitas aos dependentes, alimentos provisórios e comparecimento a programas de reeducação.", "explicacao": "Lei 11.340/2006, art. 22."}, {"id": 2000000708, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "certo_errado", "frente": "Certo ou errado? A medida protetiva depende de boletim de ocorrência ou de inquérito instaurado.", "verso": "Errado. Independe da tipificação penal, do ajuizamento de ação, da existência de inquérito ou de registro de ocorrência.", "explicacao": "Lei 11.340/2006, art. 19, § 5º (Lei 14.550/2023)."}, {"id": 2000000709, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Cabe prisão preventiva do agressor na Lei Maria da Penha?", "verso": "Sim, em qualquer fase do inquérito ou da instrução, de ofício (pela lei) ou a requerimento do MP ou representação do delegado.", "explicacao": "Lei 11.340/2006, art. 20. Após o Pacote Anticrime, prevalece a vedação da decretação de ofício (CPP, art. 311)."}, {"id": 2000000710, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Quem deve, preferencialmente, atender a mulher em situação de violência na delegacia?", "verso": "Servidoras do sexo feminino, previamente capacitadas.", "explicacao": "Lei 11.340/2006, art. 10-A."}, {"id": 2000000711, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Quando a vítima pode renunciar à representação nos crimes da Lei Maria da Penha?", "verso": "Só perante o juiz, em audiência designada para esse fim, antes do recebimento da denúncia, ouvido o MP.", "explicacao": "Lei 11.340/2006, art. 16."}, {"id": 2000000712, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "A Lei Maria da Penha exige que o agressor seja homem?", "verso": "Não. O sujeito ativo pode ser homem ou mulher; o que se exige é a violência baseada no gênero contra a mulher.", "explicacao": "Lei 11.340/2006, art. 5º, parágrafo único, e jurisprudência do STJ."}, {"id": 2000000713, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Quando um adolescente pode ser privado de sua liberdade?", "verso": "Só em flagrante de ato infracional ou por ordem escrita e fundamentada da autoridade judiciária.", "explicacao": "ECA, art. 106."}, {"id": 2000000714, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Privar adolescente de liberdade fora das hipóteses legais é crime?", "verso": "Sim: detenção de 6 meses a 2 anos.", "explicacao": "ECA, art. 230."}, {"id": 2000000715, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Deixar de liberar imediatamente adolescente apreendido ilegalmente é crime?", "verso": "Sim, para a autoridade competente que, sem justa causa, deixa de ordenar a liberação.", "explicacao": "ECA, art. 234."}, {"id": 2000000716, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Ato infracional com violência ou grave ameaça: o que a autoridade policial lavra?", "verso": "Auto de apreensão, ouvidas as testemunhas e o adolescente, com apreensão do produto e dos instrumentos.", "explicacao": "ECA, art. 173."}, {"id": 2000000717, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Comparecendo os pais, o adolescente apreendido é liberado?", "verso": "Em regra, sim, sob termo de compromisso de apresentação ao MP, salvo pela gravidade do ato ou repercussão social que exija internação.", "explicacao": "ECA, art. 174."}, {"id": 2000000718, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "O que é remissão concedida pelo MP?", "verso": "Forma de exclusão do processo, antes de iniciado o procedimento, considerando circunstâncias do fato e a personalidade do adolescente.", "explicacao": "ECA, art. 126."}, {"id": 2000000719, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "certo_errado", "frente": "Certo ou errado? Ato infracional análogo ao tráfico conduz, por si só, à internação.", "verso": "Errado.", "explicacao": "Súmula 492 do STJ."}, {"id": 2000000720, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "O que é o Conselho Tutelar?", "verso": "Órgão permanente e autônomo, não jurisdicional, encarregado de zelar pelos direitos da criança e do adolescente.", "explicacao": "ECA, art. 131."}, {"id": 2000000721, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Vender bebida alcoólica a criança ou adolescente é crime?", "verso": "Sim: detenção de 2 a 4 anos e multa.", "explicacao": "ECA, art. 243."}, {"id": 2000000722, "trilha": "policial", "materia": "leg", "assunto": "Escuta especializada", "tipo": "pares", "frente": "Escuta especializada x depoimento especial.", "verso": "Escuta especializada: entrevista sobre a violência feita pela rede de proteção, limitada ao necessário. Depoimento especial: oitiva perante a autoridade policial ou judicial.", "explicacao": "Lei 13.431/2017, arts. 7º e 8º."}, {"id": 2000000723, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Deixar arma ao alcance de menor de 18 anos ou deficiente mental, que dela se apodera, é crime?", "verso": "Sim: omissão de cautela, detenção de 1 a 2 anos e multa.", "explicacao": "Lei 10.826/2003, art. 13."}, {"id": 2000000724, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Portar arma com numeração raspada configura qual crime?", "verso": "O crime equiparado ao de arma de uso restrito (art. 16, § 1º, IV), ainda que a arma seja de uso permitido.", "explicacao": "Lei 10.826/2003, art. 16, § 1º, IV."}, {"id": 2000000725, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "certo_errado", "frente": "Certo ou errado? Portar arma desmuniciada é fato atípico.", "verso": "Errado. É crime de perigo abstrato.", "explicacao": "Jurisprudência do STF e do STJ."}, {"id": 2000000726, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Qual a pena do comércio ilegal de arma de fogo?", "verso": "Reclusão de 6 a 12 anos e multa.", "explicacao": "Lei 10.826/2003, art. 17."}, {"id": 2000000727, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Qual a pena do tráfico internacional de arma de fogo?", "verso": "Reclusão de 8 a 16 anos e multa.", "explicacao": "Lei 10.826/2003, art. 18."}, {"id": 2000000728, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Quando as penas dos crimes do Estatuto aumentam da metade (art. 20)?", "verso": "Quando praticados por integrantes dos órgãos e empresas autorizados a portar arma (ex.: policiais, guardas) ou por reincidente específico.", "explicacao": "Lei 10.826/2003, art. 20."}, {"id": 2000000729, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pares", "frente": "SINARM x SIGMA.", "verso": "SINARM: sistema da Polícia Federal para armas de civis e de diversas instituições. SIGMA: sistema do Exército para armas das Forças Armadas, colecionadores, atiradores e caçadores, entre outros.", "explicacao": "Lei 10.826/2003 e regulamentos."}, {"id": 2000000730, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "O que é tortura-castigo?", "verso": "Submeter alguém sob sua guarda, poder ou autoridade, com violência ou grave ameaça, a intenso sofrimento físico ou mental, como forma de castigo pessoal ou medida preventiva.", "explicacao": "Lei 9.455/1997, art. 1º, II."}, {"id": 2000000731, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Submeter preso a sofrimento físico ou mental por ato não previsto em lei é tortura?", "verso": "Sim, com a mesma pena do crime de tortura.", "explicacao": "Lei 9.455/1997, art. 1º, § 1º."}, {"id": 2000000732, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Quando a pena da tortura aumenta de 1/6 a 1/3?", "verso": "Se cometida por agente público; contra criança, gestante, pessoa com deficiência, adolescente ou maior de 60 anos; ou mediante sequestro.", "explicacao": "Lei 9.455/1997, art. 1º, § 4º."}, {"id": 2000000733, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Qual a pena da tortura com resultado morte?", "verso": "Reclusão de 8 a 16 anos.", "explicacao": "Lei 9.455/1997, art. 1º, § 3º. Com lesão grave ou gravíssima: 4 a 10 anos."}, {"id": 2000000734, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Roubo com arma de fogo é hediondo?", "verso": "Sim, assim como o roubo com restrição da liberdade da vítima e o roubo qualificado pela lesão grave ou morte.", "explicacao": "Lei 8.072/1990, art. 1º, II (Pacote Anticrime)."}, {"id": 2000000735, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Lesão corporal gravíssima ou seguida de morte contra policial em razão da função é hedionda?", "verso": "Sim.", "explicacao": "Lei 8.072/1990, art. 1º, I-A."}, {"id": 2000000736, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Condenado por crime hediondo com resultado morte pode obter livramento condicional?", "verso": "Não.", "explicacao": "LEP, art. 112, VI, a, e VIII (Pacote Anticrime)."}, {"id": 2000000737, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Qual a progressão de regime em hediondo com resultado morte?", "verso": "Primário: 50%. Reincidente em hediondo com morte: 70%.", "explicacao": "LEP, art. 112, VI e VIII."}, {"id": 2000000738, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "O genocídio é crime hediondo?", "verso": "Sim.", "explicacao": "Lei 8.072/1990, art. 1º, parágrafo único, I."}, {"id": 2000000739, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Quais benefícios a colaboração premiada pode trazer?", "verso": "Perdão judicial, redução da pena em até 2/3 ou substituição por restritiva de direitos; após a sentença, redução até a metade ou progressão sem os requisitos objetivos.", "explicacao": "Lei 12.850/2013, art. 4º."}, {"id": 2000000740, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "certo_errado", "frente": "Certo ou errado? Pode haver condenação baseada apenas nas declarações do colaborador.", "verso": "Errado. Nem medidas cautelares, nem recebimento de denúncia, nem sentença condenatória.", "explicacao": "Lei 12.850/2013, art. 4º, § 16."}, {"id": 2000000741, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Impedir ou embaraçar investigação de organização criminosa é crime?", "verso": "Sim, com as mesmas penas de integrar a organização.", "explicacao": "Lei 12.850/2013, art. 2º, § 1º."}, {"id": 2000000742, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Funcionário público integrante de organização criminosa pode ser afastado?", "verso": "Sim, o juiz pode determinar seu afastamento cautelar, sem prejuízo da remuneração.", "explicacao": "Lei 12.850/2013, art. 2º, § 5º."}, {"id": 2000000743, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Até quando o acordo de colaboração premiada é sigiloso?", "verso": "Até o recebimento da denúncia ou queixa.", "explicacao": "Lei 12.850/2013, art. 7º, § 3º."}, {"id": 2000000744, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Quem pode ser sujeito ativo de abuso de autoridade?", "verso": "Qualquer agente público, servidor ou não, da administração direta, indireta ou fundacional de qualquer dos Poderes, inclusive membros do Legislativo, Judiciário e MP.", "explicacao": "Lei 13.869/2019, art. 2º."}, {"id": 2000000745, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Quais os efeitos da condenação por abuso de autoridade (art. 4º)?", "verso": "Obrigação de indenizar, inabilitação para cargo público de 1 a 5 anos e perda do cargo, os dois últimos só para reincidente e se declarados na sentença.", "explicacao": "Lei 13.869/2019, art. 4º."}, {"id": 2000000746, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Interrogar preso durante o repouso noturno é abuso?", "verso": "Sim, salvo se capturado em flagrante ou se ele, assistido, consentir em prestar declarações.", "explicacao": "Lei 13.869/2019, art. 18."}, {"id": 2000000747, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Impedir que o preso se entreviste com seu advogado é crime?", "verso": "Sim.", "explicacao": "Lei 13.869/2019, art. 20."}, {"id": 2000000748, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Invadir imóvel alheio clandestinamente ou contra a vontade do ocupante, sem determinação judicial ou fora das condições legais, é crime?", "verso": "Sim.", "explicacao": "Lei 13.869/2019, art. 22. Não há crime em flagrante delito ou em caso de desastre ou socorro."}, {"id": 2000000749, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Obter prova por meio manifestamente ilícito é abuso?", "verso": "Sim, assim como usá-la conhecendo sua ilicitude.", "explicacao": "Lei 13.869/2019, art. 25."}, {"id": 2000000750, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Negar ao interessado ou seu defensor acesso aos autos de investigação é crime?", "verso": "Sim, ressalvado o acesso a peças relativas a diligências em curso ou futuras, cujo sigilo seja imprescindível.", "explicacao": "Lei 13.869/2019, art. 32."}, {"id": 2000000751, "trilha": "policial", "materia": "leg", "assunto": "Racismo", "tipo": "pergunta", "frente": "Praticar, induzir ou incitar discriminação de raça, cor, etnia, religião ou procedência nacional: qual a pena?", "verso": "Reclusão de 1 a 3 anos e multa; de 2 a 5 anos se cometido por meio de comunicação social, redes sociais ou publicação.", "explicacao": "Lei 7.716/1989, art. 20."}, {"id": 2000000752, "trilha": "policial", "materia": "leg", "assunto": "Racismo", "tipo": "pergunta", "frente": "Recusar ou impedir acesso a estabelecimento comercial por preconceito de raça ou cor é crime?", "verso": "Sim: reclusão de 1 a 3 anos.", "explicacao": "Lei 7.716/1989, art. 5º."}, {"id": 2000000753, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Qual a pena da lesão corporal culposa na direção de veículo?", "verso": "Detenção de 6 meses a 2 anos e suspensão ou proibição da habilitação.", "explicacao": "CTB, art. 303. Com embriaguez e lesão grave ou gravíssima: reclusão de 2 a 5 anos (§ 2º)."}, {"id": 2000000754, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Afastar-se do local do acidente para fugir à responsabilidade é crime?", "verso": "Sim, e o STF o considera constitucional.", "explicacao": "CTB, art. 305, e STF, RE 971.959."}, {"id": 2000000755, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Entregar a direção a pessoa não habilitada exige perigo concreto para ser crime?", "verso": "Não. É crime de perigo abstrato.", "explicacao": "Súmula 575 do STJ e CTB, art. 310."}, {"id": 2000000756, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Dirigir sem habilitação é sempre crime?", "verso": "Só se gerar perigo de dano. Sem perigo, é infração administrativa.", "explicacao": "CTB, art. 309."}, {"id": 2000000757, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Cabe substituir por pena restritiva de direitos no homicídio culposo com embriaguez (art. 302, § 3º)?", "verso": "Não.", "explicacao": "CTB, art. 312-B (Lei 14.071/2020)."}, {"id": 2000000758, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "certo_errado", "frente": "Certo ou errado? O trabalho do preso está sujeito à CLT.", "verso": "Errado.", "explicacao": "LEP, art. 28, § 2º."}, {"id": 2000000759, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Qual a remuneração mínima do trabalho do preso?", "verso": "3/4 do salário mínimo.", "explicacao": "LEP, art. 29."}, {"id": 2000000760, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "O exame criminológico é exigido para a progressão de regime?", "verso": "Sim, após a Lei 14.843/2024: a progressão depende de boa conduta e dos resultados do exame criminológico.", "explicacao": "LEP, art. 112, § 1º."}, {"id": 2000000761, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "O que a falta grave pode causar ao preso?", "verso": "Regressão de regime, perda de até 1/3 dos dias remidos, interrupção do prazo para progressão e inclusão no RDD, conforme o caso.", "explicacao": "LEP, arts. 118, 127 e 52."}, {"id": 2000000762, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Cite hipóteses de monitoração eletrônica na LEP.", "verso": "Saída temporária, prisão domiciliar, regimes aberto e semiaberto, livramento condicional e penas restritivas de direitos com limitação de horários.", "explicacao": "LEP, art. 146-B."}, {"id": 2000000763, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Quais os órgãos da execução penal?", "verso": "Conselho Nacional de Política Criminal e Penitenciária, Juízo da Execução, MP, Conselho Penitenciário, Departamentos Penitenciários, Patronato, Conselho da Comunidade e Defensoria Pública.", "explicacao": "LEP, art. 61."}, {"id": 2000000764, "trilha": "policial", "materia": "leg", "assunto": "Juizados Especiais", "tipo": "pergunta", "frente": "O que é transação penal?", "verso": "Proposta do MP de aplicação imediata de pena restritiva de direitos ou multa, sem processo, nas infrações de menor potencial ofensivo.", "explicacao": "Lei 9.099/1995, art. 76. Não gera reincidência nem antecedentes."}, {"id": 2000000765, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "O tráfico de drogas admite fiança, sursis, graça, indulto ou anistia?", "verso": "Não.", "explicacao": "Lei 11.343/2006, art. 44. O STF afastou a vedação abstrata à liberdade provisória e à substituição da pena."}, {"id": 2000000766, "trilha": "policial", "materia": "leg", "assunto": "Terrorismo", "tipo": "certo_errado", "frente": "Certo ou errado? Os atos preparatórios de terrorismo são puníveis.", "verso": "Certo, quando realizados com o propósito inequívoco de consumar o delito.", "explicacao": "Lei 13.260/2016, art. 5º."}, {"id": 2000000767, "trilha": "policial", "materia": "leg", "assunto": "Crimes ambientais", "tipo": "pergunta", "frente": "Maus-tratos a cães e gatos: qual a pena?", "verso": "Reclusão de 2 a 5 anos, multa e proibição da guarda.", "explicacao": "Lei 9.605/1998, art. 32, § 1º-A (Lei 14.064/2020)."}, {"id": 2000000768, "trilha": "policial", "materia": "leg", "assunto": "Tráfico de pessoas", "tipo": "pergunta", "frente": "Onde está tipificado o tráfico de pessoas?", "verso": "No Código Penal, art. 149-A: agenciar, recrutar, transportar ou acolher pessoa, mediante grave ameaça, violência, coação, fraude ou abuso, para remoção de órgãos, trabalho escravo, servidão, adoção ilegal ou exploração sexual.", "explicacao": "Lei 13.344/2016."}, {"id": 2000000769, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "Expor a perigo a integridade e a saúde da pessoa idosa, privando-a de cuidados, é crime?", "verso": "Sim.", "explicacao": "Lei 10.741/2003, art. 99."}, {"id": 2000000770, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "Nos crimes do Estatuto da Pessoa Idosa com pena máxima de até 4 anos, que procedimento se aplica?", "verso": "O da Lei 9.099/1995, mas sem os benefícios despenalizadores, segundo o STF.", "explicacao": "Lei 10.741/2003, art. 94, e ADI 3.096."}, {"id": 2000000771, "trilha": "policial", "materia": "leg", "assunto": "Contravenções penais", "tipo": "pergunta", "frente": "Portar arma branca (faca) em via pública configura qual infração?", "verso": "Contravenção penal de porte de arma (LCP, art. 19), segundo o STJ, enquanto não houver regulamentação.", "explicacao": "Jurisprudência do STJ."}, {"id": 2000000772, "trilha": "policial", "materia": "leg", "assunto": "Contravenções penais", "tipo": "pergunta", "frente": "O que é vias de fato?", "verso": "Agressão física sem produzir lesão corporal (ex.: empurrão, tapa sem lesão).", "explicacao": "LCP, art. 21."}, {"id": 2000000773, "trilha": "policial", "materia": "leg", "assunto": "Lei do delegado", "tipo": "pergunta", "frente": "O delegado pode ser removido do caso livremente?", "verso": "Não. Só por ato fundamentado.", "explicacao": "Lei 12.830/2013, art. 2º, § 5º."}, {"id": 2000000774, "trilha": "policial", "materia": "leg", "assunto": "Identificação criminal", "tipo": "pergunta", "frente": "A identificação criminal inclui o quê?", "verso": "Processo datiloscópico e fotográfico, juntados aos autos.", "explicacao": "Lei 12.037/2009, art. 5º. Pode incluir a coleta de material biológico para perfil genético, por decisão judicial."}, {"id": 2000000775, "trilha": "policial", "materia": "leg", "assunto": "Lavagem de dinheiro", "tipo": "pergunta", "frente": "A colaboração espontânea na lavagem de dinheiro pode gerar quais benefícios?", "verso": "Redução de 1/3 a 2/3, regime aberto ou semiaberto, perdão judicial ou substituição por restritiva de direitos.", "explicacao": "Lei 9.613/1998, art. 1º, § 5º."}, {"id": 2000000776, "trilha": "policial", "materia": "leg", "assunto": "Juizados Especiais", "tipo": "pergunta", "frente": "Na Lei 9.099, quando o autor do fato não aceita a transação penal, o que ocorre?", "verso": "O MP pode oferecer denúncia oral, seguindo-se o procedimento sumaríssimo.", "explicacao": "Lei 9.099/1995, art. 77."}, {"id": 2000000777, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Quais as espécies de ato administrativo quanto ao conteúdo?", "verso": "Normativos, ordinatórios, negociais, enunciativos e punitivos.", "explicacao": "Classificação de Hely Lopes Meirelles."}, {"id": 2000000778, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pares", "frente": "Licença x autorização x permissão.", "verso": "Licença: ato vinculado, reconhece direito (ex.: licença para construir). Autorização: discricionário e precário, interesse do particular (ex.: porte de arma). Permissão: discricionário e precário, interesse coletivo (ex.: banca de jornal).", "explicacao": "Atos negociais."}, {"id": 2000000779, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Quando a Administração pode convalidar um ato?", "verso": "Quando o defeito for sanável e não houver lesão ao interesse público nem prejuízo a terceiros.", "explicacao": "Lei 9.784/1999, art. 55."}, {"id": 2000000780, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pares", "frente": "Cassação x caducidade x contraposição.", "verso": "Cassação: o beneficiário descumpre condições. Caducidade: lei nova torna o ato incompatível. Contraposição: novo ato com efeitos opostos extingue o anterior.", "explicacao": "Formas de extinção do ato administrativo."}, {"id": 2000000781, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Em que casos a motivação do ato é obrigatória (Lei 9.784, art. 50)?", "verso": "Quando o ato nega, limita ou afeta direitos; impõe deveres ou sanções; decide licitação ou processo seletivo; dispensa licitação; decide recursos; anula, revoga ou convalida, entre outros.", "explicacao": "Lei 9.784/1999, art. 50."}, {"id": 2000000782, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Quais elementos do ato são sempre vinculados?", "verso": "Competência, finalidade e forma.", "explicacao": "Motivo e objeto podem ser discricionários."}, {"id": 2000000783, "trilha": "policial", "materia": "adm", "assunto": "Processo administrativo", "tipo": "pares", "frente": "Impedimento x suspeição na Lei 9.784.", "verso": "Impedimento: interesse direto, participação anterior como perito ou testemunha, litígio com o interessado (dever de comunicar). Suspeição: amizade íntima ou inimizade notória (pode ser arguida).", "explicacao": "Lei 9.784/1999, arts. 18 e 20."}, {"id": 2000000784, "trilha": "policial", "materia": "adm", "assunto": "Processo administrativo", "tipo": "pergunta", "frente": "Qual o prazo para a Administração decidir após concluída a instrução?", "verso": "Até 30 dias, prorrogáveis por igual período, motivadamente.", "explicacao": "Lei 9.784/1999, art. 49."}, {"id": 2000000785, "trilha": "policial", "materia": "adm", "assunto": "Processo administrativo", "tipo": "pergunta", "frente": "A quem se dirige o recurso administrativo?", "verso": "À autoridade que proferiu a decisão, que pode reconsiderar em 5 dias; se não reconsiderar, encaminha à autoridade superior.", "explicacao": "Lei 9.784/1999, art. 56, § 1º."}, {"id": 2000000786, "trilha": "policial", "materia": "adm", "assunto": "Processo administrativo", "tipo": "certo_errado", "frente": "Certo ou errado? No julgamento do recurso administrativo, a situação do recorrente pode ser agravada.", "verso": "Certo, desde que ele seja cientificado para formular alegações antes da decisão.", "explicacao": "Lei 9.784/1999, art. 64, parágrafo único. Na revisão, não pode haver agravamento (art. 65)."}, {"id": 2000000787, "trilha": "policial", "materia": "adm", "assunto": "Processo administrativo", "tipo": "pergunta", "frente": "Cite princípios expressos na Lei 9.784.", "verso": "Legalidade, finalidade, motivação, razoabilidade, proporcionalidade, moralidade, ampla defesa, contraditório, segurança jurídica, interesse público e eficiência.", "explicacao": "Lei 9.784/1999, art. 2º."}, {"id": 2000000788, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "Quais as formas de provimento na Lei 8.112?", "verso": "Nomeação, promoção, readaptação, reversão, aproveitamento, reintegração e recondução.", "explicacao": "Lei 8.112/1990, art. 8º."}, {"id": 2000000789, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pares", "frente": "Reintegração x recondução x reversão.", "verso": "Reintegração: volta do servidor demitido ilegalmente. Recondução: retorno ao cargo anterior por inabilitação em estágio probatório ou reintegração do ocupante. Reversão: retorno do aposentado à atividade.", "explicacao": "Lei 8.112/1990, arts. 25, 28 e 29."}, {"id": 2000000790, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pares", "frente": "Remoção x redistribuição.", "verso": "Remoção: deslocamento do servidor, com ou sem mudança de sede, no mesmo quadro. Redistribuição: deslocamento do cargo para outro órgão do mesmo Poder.", "explicacao": "Lei 8.112/1990, arts. 36 e 37."}, {"id": 2000000791, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "Quais as formas de vacância do cargo?", "verso": "Exoneração, demissão, promoção, readaptação, aposentadoria, posse em outro cargo inacumulável e falecimento.", "explicacao": "Lei 8.112/1990, art. 33."}, {"id": 2000000792, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "As responsabilidades civil, penal e administrativa do servidor são independentes?", "verso": "Sim, e as sanções podem se cumular.", "explicacao": "Lei 8.112/1990, arts. 121 e 125."}, {"id": 2000000793, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pares", "frente": "Abandono de cargo x inassiduidade habitual.", "verso": "Abandono: ausência intencional por mais de 30 dias consecutivos. Inassiduidade: faltas sem causa justificada por 60 dias, interpoladamente, em 12 meses. Ambos geram demissão.", "explicacao": "Lei 8.112/1990, arts. 138 e 139."}, {"id": 2000000794, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Cite casos de demissão na Lei 8.112.", "verso": "Crime contra a administração pública, abandono de cargo, inassiduidade habitual, improbidade, incontinência pública, insubordinação grave, ofensa física em serviço, aplicação irregular de dinheiro público, corrupção, entre outros.", "explicacao": "Lei 8.112/1990, art. 132."}, {"id": 2000000795, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Prazos de prescrição da ação disciplinar na Lei 8.112.", "verso": "5 anos (demissão e cassação), 2 anos (suspensão) e 180 dias (advertência).", "explicacao": "Lei 8.112/1990, art. 142."}, {"id": 2000000796, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Afastamento preventivo do servidor no PAD: prazo?", "verso": "Até 60 dias, prorrogável por igual período, sem prejuízo da remuneração.", "explicacao": "Lei 8.112/1990, art. 147."}, {"id": 2000000797, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Como é formada a comissão do PAD?", "verso": "Por 3 servidores estáveis, designados pela autoridade competente.", "explicacao": "Lei 8.112/1990, art. 149."}, {"id": 2000000798, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Quando são cancelados os registros de advertência e suspensão?", "verso": "Após 3 e 5 anos de efetivo exercício, respectivamente, se o servidor não cometer nova infração.", "explicacao": "Lei 8.112/1990, art. 131."}, {"id": 2000000799, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "pergunta", "frente": "Qual o prazo de prescrição da ação de improbidade após a Lei 14.230/2021?", "verso": "8 anos, contados da ocorrência do fato ou, nas infrações permanentes, do dia em que cessou a permanência.", "explicacao": "Lei 8.429/1992, art. 23."}, {"id": 2000000800, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "pergunta", "frente": "Quem pode propor a ação de improbidade?", "verso": "O Ministério Público. O STF restabeleceu também a legitimidade da pessoa jurídica interessada.", "explicacao": "Lei 8.429/1992, art. 17, e STF, ADIs 7.042 e 7.043."}, {"id": 2000000801, "trilha": "policial", "materia": "adm", "assunto": "Agentes públicos", "tipo": "pergunta", "frente": "Quais as espécies de agentes públicos?", "verso": "Agentes políticos, servidores públicos (estatutários, empregados e temporários), militares e particulares em colaboração com o Poder Público.", "explicacao": "Classificação doutrinária."}, {"id": 2000000802, "trilha": "policial", "materia": "adm", "assunto": "Controle", "tipo": "pares", "frente": "Tutela x autotutela.", "verso": "Tutela: controle que a administração direta exerce sobre as entidades da indireta, nos limites da lei. Autotutela: a Administração revê seus próprios atos (anula ou revoga).", "explicacao": "Súmulas 346 e 473 do STF (autotutela)."}, {"id": 2000000803, "trilha": "policial", "materia": "adm", "assunto": "Controle", "tipo": "pares", "frente": "Controle interno x externo.", "verso": "Interno: exercido pelo próprio Poder sobre seus atos. Externo: exercido por outro Poder ou órgão (ex.: Legislativo com auxílio do Tribunal de Contas).", "explicacao": "CF, arts. 70 e 74."}, {"id": 2000000804, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pergunta", "frente": "O que são agências reguladoras?", "verso": "Autarquias em regime especial, com maior autonomia, que regulam e fiscalizam setores (ex.: Anatel, Aneel, ANS).", "explicacao": "Lei 13.848/2019."}, {"id": 2000000805, "trilha": "policial", "materia": "adm", "assunto": "Serviços públicos", "tipo": "pergunta", "frente": "Quais as condições do serviço adequado (Lei 8.987)?", "verso": "Regularidade, continuidade, eficiência, segurança, atualidade, generalidade, cortesia na prestação e modicidade das tarifas.", "explicacao": "Lei 8.987/1995, art. 6º, § 1º."}, {"id": 2000000806, "trilha": "policial", "materia": "adm", "assunto": "Serviços públicos", "tipo": "certo_errado", "frente": "Certo ou errado? Interromper o serviço por inadimplemento do usuário, após aviso prévio, viola a continuidade.", "verso": "Errado. A lei permite, considerado o interesse da coletividade.", "explicacao": "Lei 8.987/1995, art. 6º, § 3º, II."}, {"id": 2000000807, "trilha": "policial", "materia": "adm", "assunto": "Intervenção na propriedade", "tipo": "pergunta", "frente": "Quais as formas de intervenção do Estado na propriedade?", "verso": "Servidão administrativa, requisição, ocupação temporária, limitação administrativa, tombamento e desapropriação.", "explicacao": "Doutrina de Direito Administrativo."}, {"id": 2000000808, "trilha": "policial", "materia": "adm", "assunto": "Intervenção na propriedade", "tipo": "pares", "frente": "Desapropriação comum x confiscatória (expropriação).", "verso": "Comum: por necessidade, utilidade pública ou interesse social, com indenização. Confiscatória: imóveis com culturas ilegais de psicotrópicos ou exploração de trabalho escravo, sem indenização.", "explicacao": "CF, arts. 5º, XXIV, e 243."}, {"id": 2000000809, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "Na omissão do Estado, qual teoria a doutrina tradicional aplica?", "verso": "Responsabilidade subjetiva, pela culpa do serviço (faute du service): o serviço não funcionou, funcionou mal ou atrasou.", "explicacao": "Há julgados do STF aplicando responsabilidade objetiva quando há dever específico de agir."}, {"id": 2000000810, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "Qual o prazo para ação de indenização contra a Fazenda Pública?", "verso": "5 anos.", "explicacao": "Decreto 20.910/1932, art. 1º."}, {"id": 2000000811, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pergunta", "frente": "Quais os critérios de julgamento da Lei 14.133?", "verso": "Menor preço, maior desconto, melhor técnica ou conteúdo artístico, técnica e preço, maior lance (leilão) e maior retorno econômico.", "explicacao": "Lei 14.133/2021, art. 33."}, {"id": 2000000812, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pergunta", "frente": "Para que serve o pregão?", "verso": "Para aquisição de bens e serviços comuns, inclusive serviços comuns de engenharia.", "explicacao": "Lei 14.133/2021, art. 6º, XLI."}, {"id": 2000000813, "trilha": "policial", "materia": "adm", "assunto": "Contratos", "tipo": "pergunta", "frente": "O que são cláusulas exorbitantes?", "verso": "Prerrogativas da Administração nos contratos: alterar e extinguir unilateralmente, fiscalizar, aplicar sanções e ocupar bens provisoriamente.", "explicacao": "Lei 14.133/2021, art. 104."}, {"id": 2000000814, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "O que é poder regulamentar?", "verso": "O poder do chefe do Executivo de editar decretos e regulamentos para a fiel execução das leis.", "explicacao": "CF, art. 84, IV."}, {"id": 2000000815, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da autotutela?", "verso": "A Administração pode anular seus atos ilegais e revogar os inconvenientes ou inoportunos, sem precisar do Judiciário.", "explicacao": "Súmulas 346 e 473 do STF."}, {"id": 2000000816, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio da supremacia do interesse público?", "verso": "O interesse público prevalece sobre o particular, justificando prerrogativas da Administração, dentro dos limites da lei.", "explicacao": "Junto com a indisponibilidade do interesse público, forma o regime jurídico-administrativo."}, {"id": 2000000817, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Indicando hora determinada, usa-se crase?", "verso": "Sim: “A audiência começa às 14h”.", "explicacao": "Também “à uma hora”."}, {"id": 2000000818, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Em que casos a crase é facultativa?", "verso": "Antes de pronome possessivo feminino singular (“à/a minha casa”), de nome próprio feminino (“à/a Maria”) e depois de “até” (“até à/a porta”).", "explicacao": "Casos clássicos de prova."}, {"id": 2000000819, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "certo_errado", "frente": "Certo ou errado? “Voltei à casa cedo”, sem especificar a casa.", "verso": "Errado. “Casa” no sentido de lar, sem determinante, não leva artigo: “Voltei a casa”.", "explicacao": "Com determinante há crase: “Voltei à casa de meus pais”."}, {"id": 2000000820, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "certo_errado", "frente": "Certo ou errado? “Fiquei frente à frente com o suspeito.”", "verso": "Errado. Não há crase em expressões com palavras repetidas: “frente a frente”, “cara a cara”, “gota a gota”.", "explicacao": "Regra das palavras repetidas."}, {"id": 2000000821, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "“Namorar” pede preposição?", "verso": "Não. É transitivo direto: “Ele namora Ana” (não “com Ana”).", "explicacao": "Na norma-padrão."}, {"id": 2000000822, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Lembrar e esquecer: quando levam preposição?", "verso": "Quando pronominais: “lembrei-me do prazo”, “esqueci-me do prazo”. Sem pronome, são diretos: “lembrei o prazo”, “esqueci o prazo”.", "explicacao": "Erro comum: “esqueci do prazo”."}, {"id": 2000000823, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Pagar e perdoar: como fica a regência?", "verso": "Coisa como objeto direto; pessoa como objeto indireto: “pagou a dívida ao banco”, “perdoou ao filho”.", "explicacao": "“Pagar o fornecedor” é corrente, mas a norma-padrão prefere “pagar ao fornecedor”."}, {"id": 2000000824, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "“Visar” no sentido de ter como objetivo pede preposição?", "verso": "Sim, “a”: “O curso visa à aprovação”.", "explicacao": "Visar no sentido de mirar ou dar visto é direto: “visou o alvo”, “visou o cheque”."}, {"id": 2000000825, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "“Simpatizar” é pronominal?", "verso": "Não: “Simpatizo com ele” (e não “simpatizo-me”).", "explicacao": "O mesmo vale para “antipatizar”."}, {"id": 2000000826, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "“Informar” admite quais construções?", "verso": "Informar algo a alguém ou informar alguém de/sobre algo: “Informei o prazo ao candidato” / “Informei o candidato do prazo”.", "explicacao": "Não se usam os dois objetos diretos."}, {"id": 2000000827, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“A maioria dos candidatos” leva o verbo no singular ou no plural?", "verso": "Ambos são aceitos: “A maioria dos candidatos passou/passaram”.", "explicacao": "Expressões partitivas admitem as duas concordâncias."}, {"id": 2000000828, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“Mais de um” leva o verbo no singular ou no plural?", "verso": "Singular: “Mais de um candidato faltou”.", "explicacao": "Plural se houver reciprocidade ou repetição: “Mais de um policial se cumprimentaram”."}, {"id": 2000000829, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“Um dos que” leva o verbo em que número?", "verso": "Em regra, plural: “Ele é um dos que mais estudam”.", "explicacao": "Singular é aceito por alguns gramáticos quando a ação é exclusiva do sujeito."}, {"id": 2000000830, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“Obrigado” e “mesmo” variam?", "verso": "Sim, concordam com quem fala ou com o termo referido: “Muito obrigada”, disse ela; “Elas mesmas assinaram”.", "explicacao": "“Mesmo” como advérbio (realmente) não varia."}, {"id": 2000000831, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“Alerta” varia?", "verso": "Não, é advérbio: “Os policiais estão alerta”.", "explicacao": "Como substantivo, varia: “os alertas”."}, {"id": 2000000832, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“Só” varia?", "verso": "Varia quando significa sozinho (“Eles estavam sós”); não varia quando significa apenas (“Só eles vieram”).", "explicacao": "Locução “a sós” é invariável."}, {"id": 2000000833, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "Sujeito composto posposto ao verbo: como concorda?", "verso": "Com o núcleo mais próximo ou com todos: “Chegou o delegado e os agentes” ou “Chegaram o delegado e os agentes”.", "explicacao": "Concordância atrativa."}, {"id": 2000000834, "trilha": "policial", "materia": "port", "assunto": "Pronomes", "tipo": "pares", "frente": "Este x esse x aquele no texto.", "verso": "Este: o que ainda vai ser dito (catafórico). Esse: o que já foi dito (anafórico). Aquele: o mais distante numa retomada de dois termos.", "explicacao": "“Disse isto: estude.” / “Estude: isso é tudo”."}, {"id": 2000000835, "trilha": "policial", "materia": "port", "assunto": "Pronomes", "tipo": "pergunta", "frente": "Qual a forma correta: “entre mim e você” ou “entre eu e você”?", "verso": "“Entre mim e você”: depois de preposição usa-se pronome oblíquo tônico.", "explicacao": "Exceção: antes de verbo no infinitivo (“para eu fazer”)."}, {"id": 2000000836, "trilha": "policial", "materia": "port", "assunto": "Pronomes", "tipo": "pergunta", "frente": "Com “a gente”, o verbo vai para que pessoa?", "verso": "3ª pessoa do singular: “A gente vai”, nunca “a gente vamos”.", "explicacao": "Na norma-padrão, prefira “nós” em textos formais."}, {"id": 2000000837, "trilha": "policial", "materia": "port", "assunto": "Pronomes", "tipo": "pergunta", "frente": "“Onde” pode retomar ideia que não seja lugar?", "verso": "Na norma-padrão, não. “Onde” só retoma lugar físico. Para outras ideias, use “em que” ou “no qual”.", "explicacao": "Errado: “Foi uma reunião onde se discutiu…”. Certo: “em que se discutiu”."}, {"id": 2000000838, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "O aposto explicativo vem entre o quê?", "verso": "Entre vírgulas (ou travessões ou parênteses): “Maria, delegada da cidade, chegou”.", "explicacao": "O aposto especificativo não leva vírgula: “o rio Amazonas”."}, {"id": 2000000839, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Adjunto adverbial deslocado para o início leva vírgula?", "verso": "Se for longo, deve; se for curto, a vírgula é facultativa.", "explicacao": "“Ontem saímos” / “Na manhã do dia seguinte, saímos”."}, {"id": 2000000840, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Para que serve o ponto e vírgula?", "verso": "Separar itens de enumeração longa, orações coordenadas extensas ou que já contêm vírgulas, e orações com conjunção adversativa deslocada.", "explicacao": "“Uns estudam; outros, não.”"}, {"id": 2000000841, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "certo_errado", "frente": "Certo ou errado? Separa-se por vírgula o verbo de seu complemento: “O delegado ouviu, as testemunhas”.", "verso": "Errado. Não se separa verbo do complemento.", "explicacao": "Mesma regra do sujeito e verbo."}, {"id": 2000000842, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Sufixos -ês/-esa x -ez/-eza.", "verso": "-ês/-esa: indicam origem ou título (português, princesa, francesa). -ez/-eza: substantivos abstratos derivados de adjetivos (rapidez, beleza).", "explicacao": "Por isso “marquesa” com S e “frieza” com Z."}, {"id": 2000000843, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "-isar x -izar.", "verso": "-isar: quando a palavra de origem já tem S (análise → analisar, pesquisa → pesquisar). -izar: quando não tem (real → realizar, útil → utilizar).", "explicacao": "Regra prática de prova."}, {"id": 2000000844, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pergunta", "frente": "Prefixo terminado em vogal + palavra iniciada por R ou S: como fica?", "verso": "Junta-se e dobra-se a consoante: antirrábico, contrassenso, autossustentável.", "explicacao": "Acordo Ortográfico de 1990."}, {"id": 2000000845, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Sessão x seção x cessão.", "verso": "Sessão: reunião, tempo de duração (sessão do júri). Seção: divisão, departamento. Cessão: ato de ceder.", "explicacao": "Clássico de prova."}, {"id": 2000000846, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Tráfego x tráfico.", "verso": "Tráfego: trânsito, fluxo. Tráfico: comércio ilegal.", "explicacao": "“Tráfego intenso” / “tráfico de drogas”."}, {"id": 2000000847, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Descrição x discrição.", "verso": "Descrição: ato de descrever. Discrição: qualidade de quem é discreto.", "explicacao": "“Agiu com discrição”."}, {"id": 2000000848, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Eminente x iminente.", "verso": "Eminente: ilustre, notável. Iminente: prestes a acontecer.", "explicacao": "“Perigo iminente” / “eminente jurista”."}, {"id": 2000000849, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Flagrante x fragrante.", "verso": "Flagrante: evidente, no ato. Fragrante: perfumado.", "explicacao": "“Preso em flagrante”."}, {"id": 2000000850, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Comprimento x cumprimento.", "verso": "Comprimento: extensão. Cumprimento: saudação ou execução (cumprimento de mandado).", "explicacao": "“Cumprimento da pena”."}, {"id": 2000000851, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Vultoso x vultuoso.", "verso": "Vultoso: volumoso, de grande vulto (quantia vultosa). Vultuoso: inchado, congestionado (rosto vultuoso).", "explicacao": "Em textos jurídicos, quase sempre “vultoso”."}, {"id": 2000000852, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "pergunta", "frente": "Qual a diferença entre “pôde” e “pode”?", "verso": "“Pôde” é pretérito perfeito (ontem ele pôde); “pode” é presente (hoje ele pode).", "explicacao": "Acento diferencial que continua no Acordo."}, {"id": 2000000853, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "pergunta", "frente": "“Têm” ou “tem”?", "verso": "“Têm” para o plural (eles têm) e “tem” para o singular (ele tem).", "explicacao": "Derivados: ele mantém / eles mantêm."}, {"id": 2000000854, "trilha": "policial", "materia": "port", "assunto": "Verbos", "tipo": "pergunta", "frente": "Como se conjuga “intervir” no pretérito perfeito (ele)?", "verso": "“Ele interveio” (como “vir”: ele veio).", "explicacao": "Errado: “ele interviu”."}, {"id": 2000000855, "trilha": "policial", "materia": "port", "assunto": "Verbos", "tipo": "pergunta", "frente": "Futuro do subjuntivo de “ver”: “quando eu ver” ou “quando eu vir”?", "verso": "“Quando eu vir”.", "explicacao": "De “vir”: “quando eu vier”."}, {"id": 2000000856, "trilha": "policial", "materia": "port", "assunto": "Verbos", "tipo": "pergunta", "frente": "Futuro do subjuntivo de “propor”:", "verso": "“Se ele propuser” (como “pôr”: se ele puser).", "explicacao": "Errado: “se ele propor”."}, {"id": 2000000857, "trilha": "policial", "materia": "port", "assunto": "Verbos", "tipo": "pares", "frente": "“Há” x “a” para tempo.", "verso": "“Há”: tempo passado (= faz): “Saiu há dois dias”. “A”: tempo futuro ou distância: “Daqui a dois dias”, “a 5 km”.", "explicacao": "“Há” no passado não leva “atrás”: evite “há dois dias atrás”."}, {"id": 2000000858, "trilha": "policial", "materia": "port", "assunto": "Morfologia", "tipo": "pares", "frente": "“Que” pronome relativo x conjunção integrante.", "verso": "Relativo: retoma um termo e pode ser trocado por “o qual” (“o livro que li”). Integrante: introduz oração substantiva e pode ser trocado por “isso” (“Sei que passou” = sei isso).", "explicacao": "Frequente em prova."}, {"id": 2000000859, "trilha": "policial", "materia": "port", "assunto": "Coesão", "tipo": "pares", "frente": "Referência anafórica x catafórica.", "verso": "Anafórica: retoma algo já dito. Catafórica: antecipa algo que ainda vai ser dito.", "explicacao": "Pronomes demonstrativos são os elementos coesivos mais cobrados."}, {"id": 2000000860, "trilha": "policial", "materia": "port", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "Quais são as funções da linguagem?", "verso": "Referencial, emotiva, conativa (apelativa), fática, metalinguística e poética.", "explicacao": "Textos técnicos e notícias: referencial. Propaganda: conativa."}, {"id": 2000000861, "trilha": "policial", "materia": "port", "assunto": "Figuras de linguagem", "tipo": "pares", "frente": "Metáfora x comparação.", "verso": "Comparação usa conectivo (“forte como um touro”). Metáfora é comparação implícita, sem conectivo (“ele é um touro”).", "explicacao": "Figuras de palavra."}, {"id": 2000000862, "trilha": "policial", "materia": "port", "assunto": "Figuras de linguagem", "tipo": "pares", "frente": "Antítese x paradoxo.", "verso": "Antítese: aproxima ideias opostas (“nasce e morre”). Paradoxo: une ideias contraditórias numa mesma afirmação (“estou cego de tanto ver”).", "explicacao": "O paradoxo também se chama oxímoro."}, {"id": 2000000863, "trilha": "policial", "materia": "port", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é pleonasmo vicioso?", "verso": "Repetição desnecessária de ideia: “subir para cima”, “elo de ligação”, “há anos atrás”.", "explicacao": "O pleonasmo literário, com intenção expressiva, é aceito."}, {"id": 2000000864, "trilha": "policial", "materia": "port", "assunto": "Interpretação", "tipo": "pares", "frente": "Polissemia x ambiguidade.", "verso": "Polissemia: a palavra tem vários sentidos conforme o contexto (manga, banco). Ambiguidade: a frase permite mais de uma leitura, geralmente indesejada.", "explicacao": "“Vi o policial com o binóculo” é ambígua."}, {"id": 2000000865, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pares", "frente": "Oração coordenada x subordinada.", "verso": "Coordenada: sintaticamente independente. Subordinada: exerce função sintática (sujeito, objeto, adjunto) em relação à principal.", "explicacao": "Coordenadas: aditivas, adversativas, alternativas, conclusivas e explicativas."}, {"id": 2000000866, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "O que é oração reduzida?", "verso": "Oração subordinada sem conjunção, com verbo no infinitivo, gerúndio ou particípio.", "explicacao": "“Ao chegar, ligou” = quando chegou, ligou."}, {"id": 2000000867, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Desde quando o Pacto de São José protege o direito à vida?", "verso": "Em geral, desde o momento da concepção.", "explicacao": "Convenção Americana, art. 4.1."}, {"id": 2000000868, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "certo_errado", "frente": "Certo ou errado? Pelo Pacto de São José, um Estado pode restabelecer a pena de morte que já aboliu.", "verso": "Errado.", "explicacao": "Convenção Americana, art. 4.3."}, {"id": 2000000869, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Qual a única prisão por dívida admitida pelo Pacto de São José?", "verso": "A do inadimplemento de obrigação alimentar.", "explicacao": "Convenção Americana, art. 7.7."}, {"id": 2000000870, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "O que é controle de convencionalidade?", "verso": "Verificar a compatibilidade das normas internas com os tratados de direitos humanos ratificados pelo país.", "explicacao": "Doutrina e jurisprudência da Corte Interamericana."}, {"id": 2000000871, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Qual foi o primeiro caso em que o Brasil foi condenado pela Corte Interamericana?", "verso": "Caso Ximenes Lopes (2006), pela morte de um paciente em clínica psiquiátrica.", "explicacao": "Corte IDH, sentença de 4 de julho de 2006."}, {"id": 2000000872, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Que caso levou a Comissão Interamericana a responsabilizar o Brasil por omissão diante da violência doméstica?", "verso": "O caso Maria da Penha Maia Fernandes (2001).", "explicacao": "Relatório 54/2001 da Comissão IDH, origem da Lei 11.340/2006."}, {"id": 2000000873, "trilha": "policial", "materia": "dh", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o princípio pro homine (pro persona)?", "verso": "Diante de várias normas ou interpretações, aplica-se a mais favorável à pessoa humana.", "explicacao": "Convenção Americana, art. 29."}, {"id": 2000000874, "trilha": "policial", "materia": "dh", "assunto": "Tortura", "tipo": "pergunta", "frente": "O que é o Protocolo de Istambul?", "verso": "Manual da ONU para investigar e documentar de forma eficaz casos de tortura e maus-tratos.", "explicacao": "Adotado em 1999."}, {"id": 2000000875, "trilha": "policial", "materia": "dh", "assunto": "Tortura", "tipo": "pergunta", "frente": "Que lei criou o Sistema Nacional de Prevenção e Combate à Tortura?", "verso": "Lei 12.847/2013, que criou também o Comitê e o Mecanismo Nacional de Prevenção e Combate à Tortura.", "explicacao": "O Mecanismo pode visitar locais de privação de liberdade sem aviso."}, {"id": 2000000876, "trilha": "policial", "materia": "dh", "assunto": "Mulheres", "tipo": "pergunta", "frente": "Qual convenção interamericana trata da violência contra a mulher?", "verso": "Convenção de Belém do Pará (1994).", "explicacao": "Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher."}, {"id": 2000000877, "trilha": "policial", "materia": "dh", "assunto": "Mulheres", "tipo": "pergunta", "frente": "Qual a convenção da ONU sobre discriminação contra a mulher?", "verso": "CEDAW (1979).", "explicacao": "Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher."}, {"id": 2000000878, "trilha": "policial", "materia": "dh", "assunto": "Crianças", "tipo": "pergunta", "frente": "Até que idade a Convenção da ONU sobre os Direitos da Criança considera a pessoa criança?", "verso": "Até 18 anos, salvo se a lei nacional fixar maioridade antes.", "explicacao": "Convenção sobre os Direitos da Criança (1989), art. 1º."}, {"id": 2000000879, "trilha": "policial", "materia": "dh", "assunto": "Migração e refúgio", "tipo": "pergunta", "frente": "Quem é refugiado pela Lei 9.474/1997?", "verso": "Quem, por fundado temor de perseguição por raça, religião, nacionalidade, grupo social ou opinião política, está fora de seu país e não pode ou não quer voltar; e quem foge de grave e generalizada violação de direitos humanos.", "explicacao": "Lei 9.474/1997, art. 1º."}, {"id": 2000000880, "trilha": "policial", "materia": "dh", "assunto": "Migração e refúgio", "tipo": "pergunta", "frente": "O que é o princípio do non-refoulement?", "verso": "Proibição de devolver o refugiado ao país onde sua vida ou liberdade esteja ameaçada.", "explicacao": "Convenção de 1951 e Lei 9.474/1997, art. 7º, § 1º."}, {"id": 2000000881, "trilha": "policial", "materia": "dh", "assunto": "Migração e refúgio", "tipo": "pares", "frente": "Deportação x expulsão x extradição.", "verso": "Deportação: retirada de quem está em situação migratória irregular. Expulsão: retirada de quem cometeu crime grave, com impedimento de reingresso. Extradição: entrega a outro país para responder a processo ou cumprir pena.", "explicacao": "Lei 13.445/2017 (Lei de Migração)."}, {"id": 2000000882, "trilha": "policial", "materia": "dh", "assunto": "Migração e refúgio", "tipo": "pergunta", "frente": "Qual princípio da Lei de Migração trata do preconceito?", "verso": "O repúdio e a prevenção à xenofobia, ao racismo e a quaisquer formas de discriminação.", "explicacao": "Lei 13.445/2017, art. 3º, II."}, {"id": 2000000883, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "Qual documento da ONU orienta a conduta dos policiais?", "verso": "O Código de Conduta para os Funcionários Responsáveis pela Aplicação da Lei (1979).", "explicacao": "Complementado pelos Princípios Básicos sobre o Uso da Força e de Armas de Fogo (1990)."}, {"id": 2000000884, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "Pelos Princípios Básicos da ONU, quando a arma de fogo pode ser usada?", "verso": "Em legítima defesa ou defesa de terceiros contra ameaça iminente de morte ou ferimento grave, ou para evitar crime grave com ameaça à vida, quando meios menos extremos forem insuficientes.", "explicacao": "Princípios Básicos sobre o Uso da Força e de Armas de Fogo (ONU, 1990), princípio 9."}, {"id": 2000000885, "trilha": "policial", "materia": "dh", "assunto": "Sistemas de proteção", "tipo": "pares", "frente": "Sistema global x sistemas regionais de direitos humanos.", "verso": "Global: ONU, com alcance mundial. Regionais: interamericano (OEA), europeu e africano, com tribunais próprios.", "explicacao": "Os sistemas são complementares."}, {"id": 2000000886, "trilha": "policial", "materia": "dh", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que são normas de jus cogens?", "verso": "Normas imperativas de direito internacional geral, que não admitem derrogação (ex.: proibição da tortura, da escravidão e do genocídio).", "explicacao": "Convenção de Viena sobre Direito dos Tratados, art. 53."}, {"id": 2000000887, "trilha": "policial", "materia": "dh", "assunto": "Instituições", "tipo": "pergunta", "frente": "Qual órgão nacional fiscaliza e monitora políticas de direitos humanos no Brasil?", "verso": "O Conselho Nacional dos Direitos Humanos (CNDH).", "explicacao": "Lei 12.986/2014."}, {"id": 2000000888, "trilha": "policial", "materia": "dh", "assunto": "Justiça de transição", "tipo": "pergunta", "frente": "O que é justiça de transição?", "verso": "Conjunto de medidas para lidar com violações em massa do passado: verdade, memória, reparação, responsabilização e reforma das instituições.", "explicacao": "No Brasil, a Comissão Nacional da Verdade (Lei 12.528/2011) atuou de 2012 a 2014."}, {"id": 2000000889, "trilha": "policial", "materia": "dh", "assunto": "CF e direitos humanos", "tipo": "pergunta", "frente": "Concessão de asilo político é princípio constitucional?", "verso": "Sim, nas relações internacionais.", "explicacao": "CF, art. 4º, X."}, {"id": 2000000890, "trilha": "policial", "materia": "dh", "assunto": "Sistema global", "tipo": "pergunta", "frente": "Qual órgão da ONU examina periodicamente a situação de direitos humanos de todos os países?", "verso": "O Conselho de Direitos Humanos, pela Revisão Periódica Universal.", "explicacao": "Criado em 2006, substituindo a Comissão de Direitos Humanos."}, {"id": 2000000891, "trilha": "policial", "materia": "dh", "assunto": "Igualdade", "tipo": "pergunta", "frente": "Qual convenção da ONU trata da eliminação da discriminação racial?", "verso": "A Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação Racial (1965).", "explicacao": "Promulgada no Brasil pelo Decreto 65.810/1969."}, {"id": 2000000892, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é spyware?", "verso": "Programa que monitora as atividades do usuário e envia as informações a terceiros.", "explicacao": "Keyloggers e screenloggers são tipos de spyware."}, {"id": 2000000893, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é uma botnet?", "verso": "Rede de computadores infectados (zumbis) controlados remotamente, usada para ataques como DDoS e envio de spam.", "explicacao": "O malware que transforma o PC em zumbi é o bot."}, {"id": 2000000894, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um ataque DDoS?", "verso": "Ataque distribuído de negação de serviço: muitos dispositivos sobrecarregam um serviço até deixá-lo indisponível.", "explicacao": "Afeta a disponibilidade."}, {"id": 2000000895, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um rootkit?", "verso": "Conjunto de programas que esconde a presença de um invasor ou malware no sistema.", "explicacao": "Difícil de detectar por antivírus comuns."}, {"id": 2000000896, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é pharming?", "verso": "Golpe que redireciona o usuário para sites falsos, mesmo digitando o endereço correto, por envenenamento de DNS.", "explicacao": "Diferente do phishing, que depende de o usuário clicar em link falso."}, {"id": 2000000897, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "Que garantias a assinatura digital oferece?", "verso": "Autenticidade, integridade e não repúdio.", "explicacao": "Não garante, por si só, a confidencialidade."}, {"id": 2000000898, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é a ICP-Brasil?", "verso": "A Infraestrutura de Chaves Públicas Brasileira, que garante a validade jurídica de documentos assinados com certificado digital.", "explicacao": "MP 2.200-2/2001."}, {"id": 2000000899, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "Para que serve uma função hash?", "verso": "Gerar um resumo de tamanho fixo de um dado, usado para verificar integridade: qualquer alteração muda o hash.", "explicacao": "Usada em assinaturas digitais e na cadeia de custódia de provas digitais."}, {"id": 2000000900, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pares", "frente": "Firewall x IDS.", "verso": "Firewall: filtra e bloqueia tráfego conforme regras. IDS: detecta e alerta sobre atividades suspeitas. O IPS, além de detectar, bloqueia.", "explicacao": "Intrusion Detection System / Intrusion Prevention System."}, {"id": 2000000901, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um sniffer?", "verso": "Programa que captura e analisa o tráfego de dados de uma rede.", "explicacao": "Pode ser usado legitimamente por administradores ou para roubar dados."}, {"id": 2000000902, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "IPv4 x IPv6.", "verso": "IPv4: 32 bits, cerca de 4,3 bilhões de endereços. IPv6: 128 bits, quantidade praticamente ilimitada.", "explicacao": "O IPv6 surgiu pelo esgotamento do IPv4."}, {"id": 2000000903, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "TCP x UDP.", "verso": "TCP: orientado à conexão, garante entrega e ordem (web, e-mail). UDP: sem conexão, mais rápido, sem garantia (streaming, jogos, DNS).", "explicacao": "Protocolos da camada de transporte."}, {"id": 2000000904, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "O que é um proxy?", "verso": "Servidor intermediário entre o usuário e a internet, que pode filtrar conteúdo, fazer cache e ocultar o IP de origem.", "explicacao": "Muito usado em redes corporativas."}, {"id": 2000000905, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "O que é o campo Cco (Bcc) no e-mail?", "verso": "Cópia oculta: os destinatários não veem os endereços uns dos outros.", "explicacao": "Boa prática ao enviar para muitas pessoas."}, {"id": 2000000906, "trilha": "policial", "materia": "inf", "assunto": "Windows", "tipo": "pergunta", "frente": "Atalho para abrir o Gerenciador de Tarefas no Windows:", "verso": "Ctrl + Shift + Esc.", "explicacao": "Ctrl + Alt + Del abre a tela de opções de segurança."}, {"id": 2000000907, "trilha": "policial", "materia": "inf", "assunto": "Windows", "tipo": "pares", "frente": "Ctrl + Z x Ctrl + Y.", "verso": "Ctrl + Z: desfazer. Ctrl + Y: refazer.", "explicacao": "Valem na maioria dos programas."}, {"id": 2000000908, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que faz a função PROCV?", "verso": "Procura um valor na primeira coluna de uma tabela e retorna o valor de outra coluna da mesma linha.", "explicacao": "=PROCV(valor;tabela;nº da coluna;FALSO) para correspondência exata."}, {"id": 2000000909, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que faz =CONT.SE(A1:A10;\"Furto\")?", "verso": "Conta quantas células de A1 a A10 contêm “Furto”.", "explicacao": "CONT.VALORES conta células não vazias; CONTAR.VAZIO conta as vazias."}, {"id": 2000000910, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que significa o erro #DIV/0! no Excel?", "verso": "Divisão por zero (ou por célula vazia).", "explicacao": "#N/D: valor não encontrado; #REF!: referência inválida; #NOME?: nome de função não reconhecido."}, {"id": 2000000911, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "Qual operador junta textos no Excel?", "verso": "O & (concatenação): =A1&\" \"&B1.", "explicacao": "Também a função CONCAT."}, {"id": 2000000912, "trilha": "policial", "materia": "inf", "assunto": "Word", "tipo": "pergunta", "frente": "Atalho para inserir quebra de página no Word:", "verso": "Ctrl + Enter.", "explicacao": "Ctrl + Shift + Enter insere quebra de coluna."}, {"id": 2000000913, "trilha": "policial", "materia": "inf", "assunto": "Word", "tipo": "pergunta", "frente": "Para que serve a mala direta?", "verso": "Gerar vários documentos personalizados (cartas, etiquetas) a partir de um modelo e uma lista de dados.", "explicacao": "Ex.: intimações com nome e endereço de cada pessoa."}, {"id": 2000000914, "trilha": "policial", "materia": "inf", "assunto": "PowerPoint", "tipo": "pergunta", "frente": "Qual tecla inicia a apresentação do PowerPoint desde o primeiro slide?", "verso": "F5.", "explicacao": "Shift + F5 inicia a partir do slide atual."}, {"id": 2000000915, "trilha": "policial", "materia": "inf", "assunto": "Sistemas", "tipo": "pergunta", "frente": "O que caracteriza o Linux?", "verso": "Sistema operacional de código aberto, multiusuário e multitarefa, com várias distribuições (Ubuntu, Debian, Fedora).", "explicacao": "O comando sudo executa tarefas com privilégios de administrador."}, {"id": 2000000916, "trilha": "policial", "materia": "inf", "assunto": "Nuvem", "tipo": "pares", "frente": "Nuvem pública x privada x híbrida.", "verso": "Pública: infraestrutura compartilhada de um provedor. Privada: exclusiva de uma organização. Híbrida: combina as duas.", "explicacao": "Modelos de implantação de nuvem."}, {"id": 2000000917, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "“P ou Q” é equivalente a qual condicional?", "verso": "“Se não P, então Q”.", "explicacao": "P ∨ Q ≡ ~P → Q."}, {"id": 2000000918, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Como se escreve “Nem P nem Q” em lógica?", "verso": "“Não P e não Q” (~P ∧ ~Q).", "explicacao": "É a negação de “P ou Q”."}, {"id": 2000000919, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pares", "frente": "Condição suficiente x condição necessária em “Se P, então Q”.", "verso": "P é condição suficiente para Q. Q é condição necessária para P.", "explicacao": "“Ser policial é suficiente para ser servidor; ser servidor é necessário para ser policial”."}, {"id": 2000000920, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "“P somente se Q” equivale a quê?", "verso": "“Se P, então Q”.", "explicacao": "Já “P se Q” equivale a “Se Q, então P”."}, {"id": 2000000921, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "certo_errado", "frente": "Certo ou errado? “Se chove, então a rua molha” equivale a “Se a rua molha, então chove”.", "verso": "Errado. Essa é a recíproca, que não é equivalente.", "explicacao": "A equivalente é a contrapositiva: “Se a rua não molha, então não chove”."}, {"id": 2000000922, "trilha": "policial", "materia": "rl", "assunto": "Problemas lógicos", "tipo": "pergunta", "frente": "Qual a estratégia básica nos problemas de verdades e mentiras?", "verso": "Supor que uma afirmação é verdadeira, testar as consequências e descartar a hipótese se houver contradição.", "explicacao": "Comece por quem faz afirmações que se contradizem."}, {"id": 2000000923, "trilha": "policial", "materia": "rl", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual o próximo termo de 1, 1, 2, 3, 5, 8, …?", "verso": "13 (sequência de Fibonacci: cada termo é a soma dos dois anteriores).", "explicacao": "8 + 5 = 13."}, {"id": 2000000924, "trilha": "policial", "materia": "rl", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual o termo geral de uma progressão geométrica?", "verso": "aₙ = a₁ · qⁿ⁻¹.", "explicacao": "q é a razão."}, {"id": 2000000925, "trilha": "policial", "materia": "rl", "assunto": "Proporção", "tipo": "pergunta", "frente": "Quando a regra de três é inversa?", "verso": "Quando uma grandeza aumenta e a outra diminui (ex.: mais policiais, menos dias para a tarefa).", "explicacao": "Nas inversas, inverte-se uma das razões antes de multiplicar em cruz."}, {"id": 2000000926, "trilha": "policial", "materia": "rl", "assunto": "Proporção", "tipo": "pergunta", "frente": "6 agentes fazem um trabalho em 10 dias. Em quantos dias 4 agentes fazem o mesmo trabalho?", "verso": "15 dias.", "explicacao": "Regra de três inversa: 6 × 10 = 4 × x → x = 15."}, {"id": 2000000927, "trilha": "policial", "materia": "rl", "assunto": "MMC e MDC", "tipo": "pergunta", "frente": "Duas viaturas passam pelo mesmo ponto a cada 12 e 18 minutos. Se passaram juntas agora, quando voltam a passar juntas?", "verso": "Em 36 minutos.", "explicacao": "MMC(12, 18) = 36."}, {"id": 2000000928, "trilha": "policial", "materia": "rl", "assunto": "MMC e MDC", "tipo": "pergunta", "frente": "Qual o maior tamanho de grupo para dividir 24 homens e 36 mulheres em grupos iguais, sem misturar?", "verso": "12 pessoas por grupo.", "explicacao": "MDC(24, 36) = 12."}, {"id": 2000000929, "trilha": "policial", "materia": "rl", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Quanto é 20% de 30% de 500?", "verso": "30.", "explicacao": "0,2 × 0,3 × 500 = 30."}, {"id": 2000000930, "trilha": "policial", "materia": "rl", "assunto": "Juros", "tipo": "pergunta", "frente": "Quais os juros simples de R$ 2.000 a 3% ao mês por 5 meses?", "verso": "R$ 300.", "explicacao": "J = C · i · t = 2.000 × 0,03 × 5."}, {"id": 2000000931, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Se a probabilidade de um evento é 0,3, qual a de ele não acontecer?", "verso": "0,7.", "explicacao": "Evento complementar: P(não A) = 1 − P(A)."}, {"id": 2000000932, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a probabilidade de tirar soma 7 com dois dados?", "verso": "1/6.", "explicacao": "6 resultados favoráveis em 36 possíveis."}, {"id": 2000000933, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "De quantas maneiras 5 pessoas podem sentar em volta de uma mesa redonda?", "verso": "24.", "explicacao": "Permutação circular: (n − 1)! = 4! = 24."}, {"id": 2000000934, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantas placas com 3 letras (26 possíveis) e 4 algarismos existem?", "verso": "26³ × 10⁴ = 175.760.000.", "explicacao": "Princípio multiplicativo, com repetição."}, {"id": 2000000935, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantos subconjuntos tem um conjunto de 5 elementos?", "verso": "32.", "explicacao": "2⁵ = 32, incluindo o vazio e o próprio conjunto."}, {"id": 2000000936, "trilha": "policial", "materia": "rl", "assunto": "Calendário", "tipo": "pergunta", "frente": "Se hoje é segunda-feira, que dia será daqui a 100 dias?", "verso": "Quarta-feira.", "explicacao": "100 ÷ 7 deixa resto 2: segunda + 2 = quarta."}, {"id": 2000000937, "trilha": "policial", "materia": "rl", "assunto": "Média", "tipo": "pergunta", "frente": "Como se calcula a média ponderada?", "verso": "Soma dos valores multiplicados pelos pesos, dividida pela soma dos pesos.", "explicacao": "Ex.: notas 6 (peso 2) e 9 (peso 1): (12 + 9)/3 = 7."}, {"id": 2000000938, "trilha": "policial", "materia": "rl", "assunto": "Conjuntos", "tipo": "pergunta", "frente": "O que é A − B (diferença)?", "verso": "Os elementos que estão em A e não estão em B.", "explicacao": "Não confundir com B − A."}, {"id": 2000000939, "trilha": "policial", "materia": "rl", "assunto": "Lógica de argumentação", "tipo": "pergunta", "frente": "Premissas: “Todo policial é servidor” e “João é policial”. Conclusão válida?", "verso": "João é servidor.", "explicacao": "Silogismo válido (modus ponens com quantificador)."}, {"id": 2000000940, "trilha": "policial", "materia": "rl", "assunto": "Lógica de argumentação", "tipo": "certo_errado", "frente": "Certo ou errado? De “Todo policial é servidor” e “Maria é servidora” conclui-se que Maria é policial.", "verso": "Errado. É a falácia de afirmar o consequente.", "explicacao": "Ser servidor é necessário, mas não suficiente, para ser policial."}, {"id": 2000000941, "trilha": "policial", "materia": "rl", "assunto": "Frações", "tipo": "pergunta", "frente": "Um terço de um inquérito foi lido na segunda e metade do restante na terça. Que fração falta?", "verso": "1/3.", "explicacao": "Sobram 2/3; metade disso (1/3) é lida; resta 1/3."}, {"id": 2000000942, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é a mancha de Sommer-Larcher?", "verso": "Faixa escura na esclera, por desidratação, quando os olhos ficam abertos após a morte.", "explicacao": "Fenômeno abiótico consecutivo."}, {"id": 2000000943, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Em média, quanto o cadáver esfria por hora nas primeiras horas?", "verso": "Cerca de 1 a 1,5 °C por hora (algidez cadavérica).", "explicacao": "Varia com ambiente, roupas e massa corporal."}, {"id": 2000000944, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é espasmo cadavérico?", "verso": "Rigidez instantânea que fixa a última posição em vida, sem relaxamento prévio.", "explicacao": "Comum em mortes violentas com grande tensão (ex.: mão segurando a arma)."}, {"id": 2000000945, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pares", "frente": "Sinais abióticos imediatos x consecutivos.", "verso": "Imediatos: perda da consciência, parada respiratória e circulatória, insensibilidade, imobilidade. Consecutivos: resfriamento, desidratação, livores e rigidez.", "explicacao": "Classificação dos sinais de morte."}, {"id": 2000000946, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pares", "frente": "Morte natural x violenta x suspeita.", "verso": "Natural: por doença ou causa interna. Violenta: por causa externa (homicídio, suicídio, acidente). Suspeita: causa indeterminada que levanta dúvida.", "explicacao": "Mortes violentas e suspeitas exigem necropsia pelo IML."}, {"id": 2000000947, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pares", "frente": "Ferida incisa x perfuroincisa.", "verso": "Incisa (instrumento cortante): comprimento maior que a profundidade. Perfuroincisa (perfurocortante): profundidade maior que o comprimento.", "explicacao": "Ex.: navalha x faca de ponta."}, {"id": 2000000948, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "O que indica a cauda de escoriação numa ferida incisa?", "verso": "O fim do movimento do instrumento, indicando a direção do corte.", "explicacao": "Ajuda a reconstituir a dinâmica."}, {"id": 2000000949, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "O que são lesões de defesa?", "verso": "Ferimentos nas mãos e antebraços produzidos quando a vítima tenta se proteger.", "explicacao": "Indicam que a vítima estava consciente e reagiu."}, {"id": 2000000950, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "Como são as bordas da ferida contusa?", "verso": "Irregulares, com pontes de tecido entre elas e escoriações ao redor.", "explicacao": "Produzida por instrumento contundente."}, {"id": 2000000951, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "Como se distingue lesão produzida em vida de lesão post mortem?", "verso": "Pelas reações vitais: hemorragia infiltrada, coagulação, retração dos tecidos e reação inflamatória.", "explicacao": "Lesões post mortem não sangram de forma infiltrada."}, {"id": 2000000952, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "O que são as manchas de Tardieu?", "verso": "Pequenas hemorragias puntiformes (petéquias) em pleuras e outras superfícies, comuns nas asfixias.", "explicacao": "Sinal geral, não específico, de asfixia."}, {"id": 2000000953, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "O que são estigmas ungueais?", "verso": "Marcas semilunares de unhas no pescoço, típicas da esganadura.", "explicacao": "Indicam compressão com as mãos."}, {"id": 2000000954, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "O que é a “mão de lavadeira” no afogado?", "verso": "Enrugamento e esbranquiçamento da pele das mãos e pés pela maceração na água.", "explicacao": "Indica permanência na água, não necessariamente afogamento em vida."}, {"id": 2000000955, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pares", "frente": "Sufocação direta x indireta.", "verso": "Direta: obstrução dos orifícios respiratórios (nariz e boca) ou das vias aéreas. Indireta: compressão do tórax que impede a respiração.", "explicacao": "Formas de asfixia mecânica."}, {"id": 2000000956, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "O que é asfixia por confinamento?", "verso": "A que ocorre em ambiente fechado e restrito, pelo consumo do oxigênio e acúmulo de gás carbônico.", "explicacao": "Ex.: pessoa trancada em porta-malas."}, {"id": 2000000957, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pergunta", "frente": "Qual a marca típica da corrente elétrica industrial na pele?", "verso": "Marca elétrica de Jellinek: lesão endurecida, deprimida e esbranquiçada, no ponto de entrada.", "explicacao": "Raio (eletricidade natural): sinal de Lichtenberg."}, {"id": 2000000958, "trilha": "policial", "materia": "ml", "assunto": "Infanticídio", "tipo": "pergunta", "frente": "Qual exame verifica se o recém-nascido respirou (nasceu com vida)?", "verso": "A docimásia hidrostática pulmonar de Galeno: pulmão que flutua indica respiração.", "explicacao": "Prova de vida extrauterina."}, {"id": 2000000959, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Que exame identifica pelo exame dos dentes?", "verso": "A identificação odontolegal (arcada dentária).", "explicacao": "Muito útil em corpos carbonizados."}, {"id": 2000000960, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Que método de identificação se baseava em medidas corporais?", "verso": "A antropometria de Bertillon.", "explicacao": "Substituída pela datiloscopia, mais confiável."}, {"id": 2000000961, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Qual osso é o melhor para diagnosticar o sexo do esqueleto?", "verso": "A pelve (bacia).", "explicacao": "O crânio vem em segundo lugar."}, {"id": 2000000962, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pares", "frente": "Identidade x identificação.", "verso": "Identidade: conjunto de características que tornam a pessoa única. Identificação: processo técnico para determinar essa identidade.", "explicacao": "Conceitos básicos da Medicina Legal."}, {"id": 2000000963, "trilha": "policial", "materia": "ml", "assunto": "Toxicologia", "tipo": "pergunta", "frente": "Como se mede a embriaguez alcoólica para fins legais?", "verso": "Pela alcoolemia (concentração de álcool no sangue) ou pelo etilômetro (ar alveolar).", "explicacao": "CTB, art. 306."}, {"id": 2000000964, "trilha": "policial", "materia": "ml", "assunto": "Lesões", "tipo": "pergunta", "frente": "O que é escoriação?", "verso": "Lesão superficial com arrancamento da epiderme, que expõe a derme.", "explicacao": "Produzida por instrumento contundente que desliza na pele."}, {"id": 2000000965, "trilha": "policial", "materia": "ml", "assunto": "Documentos", "tipo": "pergunta", "frente": "O que é atestado médico?", "verso": "Afirmação simples, por escrito, de um fato médico e suas consequências.", "explicacao": "Atestado falso é crime (CP, art. 302)."}, {"id": 2000000966, "trilha": "policial", "materia": "ml", "assunto": "Perícia", "tipo": "pergunta", "frente": "O que é exumação e quando é feita?", "verso": "Desenterrar o cadáver para exame, com dia e hora previamente marcados pela autoridade.", "explicacao": "CPP, art. 163."}, {"id": 2000000967, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "Qual o objetivo do Estatuto da Igualdade Racial?", "verso": "Garantir à população negra a igualdade de oportunidades, a defesa de direitos e o combate à discriminação e à intolerância étnica.", "explicacao": "Lei 12.288/2010, art. 1º."}, {"id": 2000000968, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "O que é desigualdade racial pelo Estatuto?", "verso": "Toda situação injustificada de diferenciação de acesso e fruição de bens, serviços e oportunidades, em razão de raça, cor, descendência ou origem étnica.", "explicacao": "Lei 12.288/2010, art. 1º, parágrafo único, II."}, {"id": 2000000969, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pergunta", "frente": "O que é racismo estrutural?", "verso": "Racismo enraizado no funcionamento normal das instituições e da sociedade, que reproduz desigualdades mesmo sem intenção individual.", "explicacao": "Conceito usado em políticas públicas e na formação policial."}, {"id": 2000000970, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pergunta", "frente": "Racismo religioso: a intolerância contra religiões de matriz africana é crime?", "verso": "Sim. A discriminação por religião está na Lei 7.716/1989.", "explicacao": "Lei 7.716/1989, art. 20."}, {"id": 2000000971, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pergunta", "frente": "Injúria racial praticada por funcionário público no exercício da função tem a pena aumentada?", "verso": "Sim, de 1/3 até a metade.", "explicacao": "Lei 7.716/1989, art. 20-B (Lei 14.532/2023), também para o crime do art. 20."}, {"id": 2000000972, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O que é feminicídio?", "verso": "Matar mulher por razões da condição do sexo feminino (violência doméstica e familiar, ou menosprezo e discriminação à condição de mulher).", "explicacao": "CP, art. 121-A."}, {"id": 2000000973, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "Pessoas trans podem mudar nome e gênero no registro civil sem cirurgia ou ação judicial?", "verso": "Sim, diretamente no cartório.", "explicacao": "STF, ADI 4.275 (2018), e Provimento CNJ 73/2018."}, {"id": 2000000974, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "Como deve ser tratado o nome social nos órgãos federais?", "verso": "Deve ser respeitado e usado no tratamento da pessoa travesti ou transexual.", "explicacao": "Decreto 8.727/2016."}, {"id": 2000000975, "trilha": "policial", "materia": "igual", "assunto": "Povos tradicionais", "tipo": "pergunta", "frente": "O que garante a Constituição aos remanescentes de quilombos?", "verso": "A propriedade definitiva das terras que estejam ocupando, devendo o Estado emitir os títulos.", "explicacao": "ADCT, art. 68."}, {"id": 2000000976, "trilha": "policial", "materia": "igual", "assunto": "Igualdade", "tipo": "pares", "frente": "Igualdade formal x material.", "verso": "Formal: todos são iguais perante a lei. Material: tratar desigualmente os desiguais, na medida de sua desigualdade, para alcançar igualdade real.", "explicacao": "Base das ações afirmativas."}, {"id": 2000000977, "trilha": "policial", "materia": "est", "assunto": "Medidas", "tipo": "pergunta", "frente": "Qual a mediana de 3, 7, 9, 12?", "verso": "8.", "explicacao": "Com quantidade par, é a média dos dois centrais: (7 + 9)/2."}, {"id": 2000000978, "trilha": "policial", "materia": "est", "assunto": "Dispersão", "tipo": "pergunta", "frente": "O que é coeficiente de variação?", "verso": "Desvio padrão dividido pela média (em %). Compara a dispersão de conjuntos diferentes.", "explicacao": "CV alto indica dados muito dispersos."}, {"id": 2000000979, "trilha": "policial", "materia": "est", "assunto": "Gráficos", "tipo": "pergunta", "frente": "Que gráfico é indicado para mostrar partes de um todo?", "verso": "Gráfico de setores (pizza).", "explicacao": "Para evolução no tempo, o gráfico de linhas."}, {"id": 2000000980, "trilha": "policial", "materia": "est", "assunto": "Distribuição", "tipo": "pergunta", "frente": "Na distribuição normal, onde ficam média, moda e mediana?", "verso": "No mesmo ponto, no centro da curva simétrica.", "explicacao": "Cerca de 68% dos dados ficam a até 1 desvio padrão da média."}, {"id": 2000000981, "trilha": "policial", "materia": "est", "assunto": "Amostragem", "tipo": "pergunta", "frente": "O que é amostragem aleatória simples?", "verso": "Todos os elementos da população têm a mesma chance de serem escolhidos.", "explicacao": "Estratificada: a população é dividida em grupos e se sorteia em cada um."}, {"id": 2000000982, "trilha": "policial", "materia": "cont", "assunto": "Fundamentos", "tipo": "pares", "frente": "Ativo x passivo.", "verso": "Ativo: bens e direitos da entidade. Passivo: obrigações com terceiros.", "explicacao": "Patrimônio líquido = ativo − passivo."}, {"id": 2000000983, "trilha": "policial", "materia": "cont", "assunto": "Fundamentos", "tipo": "pergunta", "frente": "O que é situação patrimonial de passivo a descoberto?", "verso": "Quando o passivo é maior que o ativo (patrimônio líquido negativo).", "explicacao": "Também chamada de situação líquida negativa."}, {"id": 2000000984, "trilha": "policial", "materia": "cont", "assunto": "Contas", "tipo": "pares", "frente": "Contas patrimoniais x de resultado.", "verso": "Patrimoniais: ativo, passivo e PL (aparecem no balanço). De resultado: receitas e despesas (apuram o lucro ou prejuízo).", "explicacao": "As de resultado são encerradas no fim do exercício."}, {"id": 2000000985, "trilha": "policial", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Qual livro registra os fatos contábeis em ordem cronológica?", "verso": "O livro Diário.", "explicacao": "O Razão organiza por conta."}, {"id": 2000000986, "trilha": "policial", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "O que mostra a DRE?", "verso": "A Demonstração do Resultado do Exercício: receitas, custos e despesas do período, chegando ao lucro ou prejuízo.", "explicacao": "Lei 6.404/1976, art. 187."}, {"id": 2000000987, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é desenho universal?", "verso": "Concepção de produtos, ambientes e serviços usáveis por todas as pessoas, sem necessidade de adaptação.", "explicacao": "Lei 13.146/2015, art. 3º, II."}, {"id": 2000000988, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Quais os tipos de barreira do Estatuto?", "verso": "Urbanísticas, arquitetônicas, nos transportes, nas comunicações e na informação, atitudinais e tecnológicas.", "explicacao": "Lei 13.146/2015, art. 3º, IV."}, {"id": 2000000989, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é tomada de decisão apoiada?", "verso": "Processo em que a pessoa com deficiência escolhe duas pessoas de confiança para apoiá-la em decisões da vida civil.", "explicacao": "Código Civil, art. 1.783-A."}, {"id": 2000000990, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Qual o percentual mínimo de vagas para pessoas com deficiência em concursos federais?", "verso": "5%, segundo o regulamento federal (a lei permite até 20%).", "explicacao": "Decreto 9.508/2018 e Lei 8.112/1990, art. 5º, § 2º."}, {"id": 2000000991, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Abandonar pessoa com deficiência em hospitais, abrigos ou congêneres é crime?", "verso": "Sim: reclusão de 6 meses a 3 anos e multa.", "explicacao": "Lei 13.146/2015, art. 90."}, {"id": 2000000992, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é um modelo de linguagem (LLM)?", "verso": "Sistema de IA treinado com grandes volumes de texto para entender e gerar linguagem natural.", "explicacao": "Base dos chatbots atuais."}, {"id": 2000000993, "trilha": "policial", "materia": "ia", "assunto": "Riscos", "tipo": "pergunta", "frente": "O que é “alucinação” em IA generativa?", "verso": "Quando o sistema produz informação falsa ou inventada com aparência de verdadeira.", "explicacao": "Por isso respostas de IA devem ser checadas em fontes oficiais."}, {"id": 2000000994, "trilha": "policial", "materia": "ia", "assunto": "Aplicações", "tipo": "pergunta", "frente": "Cite usos de IA na segurança pública.", "verso": "Reconhecimento facial e de placas, análise de manchas criminais, triagem de denúncias e análise de grandes volumes de dados.", "explicacao": "Exigem cuidado com privacidade, vieses e controle humano."}, {"id": 2000000995, "trilha": "policial", "materia": "ia", "assunto": "Proteção de dados", "tipo": "pergunta", "frente": "A LGPD dá direito de revisão de decisões automatizadas?", "verso": "Sim. O titular pode pedir revisão de decisões tomadas só com base em tratamento automatizado que afetem seus interesses.", "explicacao": "Lei 13.709/2018, art. 20."}, {"id": 2000000996, "trilha": "policial", "materia": "ia", "assunto": "Inovação", "tipo": "pergunta", "frente": "O que é a Lei do Governo Digital?", "verso": "Lei que estabelece princípios e instrumentos para aumentar a eficiência da administração pública por meio da desburocratização e da transformação digital.", "explicacao": "Lei 14.129/2021."}, {"id": 2000000997, "trilha": "policial", "materia": "sust", "assunto": "Gestão pública", "tipo": "pergunta", "frente": "O que é o desenvolvimento nacional sustentável nas licitações?", "verso": "Um dos objetivos da licitação: considerar impactos ambientais e sociais nas compras públicas.", "explicacao": "Lei 14.133/2021, art. 11, IV."}, {"id": 2000000998, "trilha": "policial", "materia": "sust", "assunto": "Resíduos", "tipo": "pergunta", "frente": "O que é logística reversa?", "verso": "Conjunto de ações para devolver resíduos ao setor empresarial para reaproveitamento ou destinação adequada.", "explicacao": "Lei 12.305/2010 (Política Nacional de Resíduos Sólidos)."}, {"id": 2000000999, "trilha": "policial", "materia": "sust", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que significa a sigla ESG?", "verso": "Environmental, Social and Governance: práticas ambientais, sociais e de governança.", "explicacao": "Usada para avaliar responsabilidade de organizações."}, {"id": 2000001000, "trilha": "policial", "materia": "sust", "assunto": "Clima", "tipo": "pergunta", "frente": "Qual acordo internacional busca limitar o aquecimento global bem abaixo de 2 °C?", "verso": "O Acordo de Paris (2015).", "explicacao": "Com esforços para limitar a 1,5 °C."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
